const LIMITE_SPAZIO_MB = 300;
let spazioInCache = { quando: 0, byte: null };
async function spazioUsatoByte(forza = false) {
  if (!forza && Date.now() - spazioInCache.quando < 60000) return spazioInCache.byte;
  const { data, error } = await supabase.rpc("spazio_usato");
  spazioInCache = { quando: Date.now(), byte: error ? null : Number(data) || 0 }; // null = funzione non ancora creata: nessun limite
  return spazioInCache.byte;
}
