function formatData(d) {
  if (!d) return "—";
  const date = new Date(d);
  return date.toLocaleDateString("it-IT", { day: "numeric", month: "short", year: "numeric" });
}

// converte l'URL remoto di una foto salvata in una dataURL utilizzabile dal PDF
async function urlToDataUrl(url) {
  let blob;
  if (eRiservato(url)) {
    const { data, error } = await supabase.storage.from(BUCKET_RISERVATO).download(percorsoRiservato(url));
    if (error) throw error;
    blob = data;
  } else {
    const res = await fetch(url);
    blob = await res.blob();
  }
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

// carica un'immagine da dataUrl e restituisce l'oggetto Image pronto (per ritagliarne pezzi con canvas)
function caricaImmagine(dataUrl) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = dataUrl;
  });
}

