export default function App() {
  // informativa privacy e condizioni d'uso: pagine pubbliche
  const percorso = window.location.pathname.replace(/\/+$/, "");
  if (percorso === "/privacy") return <Suspense fallback={null}><PaginaPrivacy /></Suspense>;
  if (percorso === "/termini") return <Suspense fallback={null}><PaginaTermini /></Suspense>;
  // link di consegna al cliente: pagina pubblica, senza login
  const tokenGalleria = new URLSearchParams(window.location.search).get("galleria");
  if (tokenGalleria) return <GalleriaCondivisa token={tokenGalleria} />;
  // pagina pubblica del pilota: app.eyedrones.it/p/nome (o ?pilota=nome), senza login
  const slugPilota = slugPilotaDaIndirizzo();
  if (slugPilota) return <PaginaPilotaPubblica slug={slugPilota} />;
  return <AppAutenticata />;
}

// messaggi di Supabase Auth tradotti in parole semplici
function erroreAccessoItaliano(msg) {
  const m = String(msg || "");
  if (/invalid login credentials/i.test(m)) return "Email o password non corretti.";
  if (/email not confirmed/i.test(m)) return "Devi prima confermare l'email: apri il link che ti abbiamo mandato (guarda anche nello spam).";
  if (/already registered|already been registered|already exists/i.test(m)) return "Esiste già un account con questa email: accedi, oppure usa «Password dimenticata?».";
  if (/password should be at least|at least \d+ characters/i.test(m)) return "La password deve avere almeno 6 caratteri.";
  if (/should be different|same password/i.test(m)) return "La nuova password deve essere diversa da quella vecchia.";
  if (/rate limit|security purposes|too many/i.test(m)) return "Troppe richieste in poco tempo: riprova tra qualche minuto.";
  if (/invalid.*email|unable to validate email|email address .* is invalid/i.test(m)) return "Indirizzo email non valido.";
  if (/expired|invalid.*(token|link)|otp/i.test(m)) return "Il link è scaduto o è già stato usato: chiedine uno nuovo.";
  if (/failed to fetch|network/i.test(m)) return "Connessione assente: controlla internet e riprova.";
  return m || "Si è verificato un errore, riprova.";
}

// scelta della nuova password dopo il link "Password dimenticata?" (e anche da Impostazioni)
function NuovaPassword({ onFatto, dentroApp = false }) {
  const [password, setPassword] = useState("");
  const [ripeti, setRipeti] = useState("");
  const [errore, setErrore] = useState(null);
  const [fatto, setFatto] = useState(false);
  const [salvando, setSalvando] = useState(false);
  const salva = async (e) => {
    e.preventDefault();
    setErrore(null);
    if (password.length < 6) { setErrore("La password deve avere almeno 6 caratteri."); return; }
    if (password !== ripeti) { setErrore("Le due password non coincidono."); return; }
    setSalvando(true);
    const { error } = await supabase.auth.updateUser({ password });
    setSalvando(false);
    if (error) { setErrore(erroreAccessoItaliano(error.message)); return; }
    setFatto(true);
    setPassword(""); setRipeti("");
  };
  const modulo = (
    <form onSubmit={salva} style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      <input type="password" autoComplete="new-password" placeholder="Nuova password (almeno 6 caratteri)" value={password} onChange={(e) => setPassword(e.target.value)} style={inputStyle} />
      <input type="password" autoComplete="new-password" placeholder="Ripeti la nuova password" value={ripeti} onChange={(e) => setRipeti(e.target.value)} style={inputStyle} />
      {errore && <p style={{ fontSize: 12, color: "#ff9c9c", margin: 0 }}>{errore}</p>}
      {fatto && <p style={{ fontSize: 12, color: "#4ade80", margin: 0 }}>✓ Password cambiata.</p>}
      <button type="submit" disabled={salvando} style={{ background: "linear-gradient(90deg, #e0552f, #ff8c42)", color: "#161a1f", border: "none", borderRadius: 6, padding: "10px 0", fontWeight: 700, fontSize: 13.5 }}>{salvando ? "Salvo…" : "Salva la nuova password"}</button>
      {fatto && onFatto && <button type="button" onClick={onFatto} style={{ background: "none", border: "1px solid #333a45", color: "#e7eaee", borderRadius: 6, padding: "9px 0", fontSize: 13 }}>Entra nell'app</button>}
    </form>
  );
  if (dentroApp) return modulo;
  return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'IBM Plex Sans', sans-serif", padding: 24 }}>
      <div style={{ width: "100%", maxWidth: 340 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, justifyContent: "center", marginBottom: 20 }}>
          <img src={LOGO_EYEDRONES} alt="" style={{ width: 40, height: 40 }} />
          <span style={{ fontWeight: 700, fontSize: 18, color: "#e7eaee" }}>EyeDrones</span>
        </div>
        <h1 style={{ fontSize: 18, color: "#e7eaee", margin: "0 0 4px 0", textAlign: "center" }}>Scegli una nuova password</h1>
        <p style={{ fontSize: 12.5, color: "#8b95a3", margin: "0 0 16px 0", textAlign: "center" }}>Hai aperto il link per reimpostarla: scrivi quella nuova.</p>
        {modulo}
      </div>
    </div>
  );
}

// provenienza degli iscritti (?ref=facebook, ?ref=instagram, ?ref=pinotti...): solo lettere, numeri, - e _
const pulisciRef = (v) => {
  const r = String(v || "").trim().toLowerCase().replace(/[^a-z0-9_-]/g, "").slice(0, 40);
  return r || null;
};
const SITI_PROVENIENZA = [[/dronezine/, "dronezine"], [/facebook|fb\.com|fb\.me/, "facebook"], [/instagram/, "instagram"], [/tiktok/, "tiktok"], [/linkedin|lnkd\.in/, "linkedin"], [/youtube|youtu\.be/, "youtube"], [/google\./, "google"], [/bing\.|duckduckgo/, "ricerca"], [/whatsapp|wa\.me/, "whatsapp"], [/t\.me|telegram/, "telegram"]];
function provenienzaDaSito() {
  try {
    const q = new URLSearchParams(window.location.search);
    if (q.get("fbclid")) return "facebook";
    if (q.get("igshid")) return "instagram";
    if (q.get("ttclid")) return "tiktok";
    const host = document.referrer ? new URL(document.referrer).hostname.toLowerCase() : "";
    if (!host || host === window.location.hostname) return null;
    const trovato = SITI_PROVENIENZA.find(([r]) => r.test(host));
    return pulisciRef(trovato ? trovato[1] : host.replace(/^www\./, "").split(".").slice(-2, -1)[0]);
  } catch { return null; }
}
const refSalvato = () => {
  try { return pulisciRef(localStorage.getItem("eyedrones_ref")); } catch { return null; }
};

// --- Copia dei documenti di controllo sul telefono (per i controlli dove non c'è campo) ---------------
// solo dati di testo (attestati, droni, permessi, piani vicini): i file allegati richiedono la rete
const CHIAVE_COPIA_CONTROLLO = "eyedrones_copia_controllo";
function leggiCopiaControllo() {
  try { const c = JSON.parse(localStorage.getItem(CHIAVE_COPIA_CONTROLLO) || "null"); return c && typeof c === "object" ? c : null; } catch { return null; }
}
function salvaCopiaControllo(parziale) {
  try {
    const attuale = leggiCopiaControllo() || {};
    localStorage.setItem(CHIAVE_COPIA_CONTROLLO, JSON.stringify({ ...attuale, ...parziale, salvato: new Date().toISOString() }));
  } catch { /* memoria piena o non disponibile: pazienza */ }
}
function cancellaCopiaControllo() {
  try { localStorage.removeItem(CHIAVE_COPIA_CONTROLLO); } catch { /* niente */ }
}
const esciDallAccount = () => { cancellaCopiaControllo(); supabase.auth.signOut(); };
// tiene solo i piani da ieri in avanti, per non riempire la memoria
const pianiPerCopia = (piani) => (piani || []).filter((x) => !x.data_prevista || x.data_prevista >= dataLocale(-1)).slice(0, 30);

// --- Batterie e temperatura ------------------------------------------------------------------------------
function avvisoBatterieTemperatura(t) {
  if (t == null || Number.isNaN(Number(t))) return null;
  const v = Math.round(Number(t));
  if (v < 0) return { colore: "#7fb0ff", testo: `🥶 ${v} °C, sotto zero: batterie al caldo (in tasca o in auto) fino al decollo, 1 minuto in volo stazionario prima di partire, voli brevi e atterra con il 30–40%. Attento al ghiaccio sulle eliche e controlla nel manuale la temperatura minima del drone.` };
  if (v < 10) return { colore: "#7fb0ff", testo: `❄️ ${v} °C: fa freddo per le batterie. Tienile al caldo fino al decollo, aspetta qualche secondo in volo stazionario, conta su meno autonomia e atterra con più margine.` };
  if (v > 35) return { colore: "#ff8c42", testo: `🔥 ${v} °C: molto caldo. Non lasciare drone e batterie al sole o in auto, falle raffreddare prima di ricaricarle e fai voli più corti.` };
  return null;
}

// --- Aggiungi al calendario -----------------------------------------------------------------------------
function calendarioDaPiano(p, drone) {
  const ora = p.ora_prevista ? String(p.ora_prevista).slice(0, 5) : "";
  const tipo = ETICHETTE_TIPO_PIANO[p.tipo_ispezione] || p.tipo_ispezione || "Volo";
  return datiCalendarioPiano({
    data: p.data_prevista, ora,
    titolo: `🚁 ${tipo} · ${p.impianto_nome || "Volo con drone"}`,
    luogo: [p.impianto_nome, p.checklist_stato?.zona?.punto].filter(Boolean).join(" · "),
    dettagli: [drone ? `Drone: ${drone.nome}` : "", "Prima di partire apri EyeDrones: meteo, zona, checklist e documenti per il controllo.", "https://app.eyedrones.it"].filter(Boolean).join("\n"),
  });
}
// navigatore verso il luogo del piano: coordinate della verifica zona o del luogo, altrimenti il nome scritto
function destinazionePiano(p) {
  const c = leggiCoordinate(p?.checklist_stato?.zona?.punto) || leggiCoordinate(p?.luogo_coordinate);
  if (c) return { c, testo: `${c.lat.toFixed(6)},${c.lon.toFixed(6)}` };
  const nome = String(p?.impianto_nome || "").trim();
  return nome ? { c: null, testo: nome } : null;
}
function PulsantiNavigatore({ piano }) {
  const d = destinazionePiano(piano);
  if (!d) return null;
  const maps = `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(d.testo)}`;
  const waze = d.c ? `https://waze.com/ul?ll=${d.c.lat.toFixed(6)},${d.c.lon.toFixed(6)}&navigate=yes` : `https://waze.com/ul?q=${encodeURIComponent(d.testo)}&navigate=yes`;
  const st = { display: "inline-flex", alignItems: "center", gap: 5, background: "#13202e", border: "1px solid #2a4562", color: "#8fc1ff", borderRadius: 5, padding: "5px 10px", fontSize: 11.5, fontWeight: 600, textDecoration: "none" };
  return (
    <>
      <a href={maps} target="_blank" rel="noreferrer" style={st} title={d.c ? "Porta al punto del volo" : "Cerca il luogo per nome"}>🧭 Google Maps</a>
      <a href={waze} target="_blank" rel="noreferrer" style={st}>🚗 Waze</a>
    </>
  );
}

function AppAutenticata() {
  const [session, setSession] = useState(undefined); // undefined = ancora in caricamento, null = non loggato
  // aperto il link "Password dimenticata?": prima di entrare si sceglie la nuova password
  const [recupero, setRecupero] = useState(() => /type=recovery/.test(window.location.hash));
  // senza rete e senza accesso valido si possono comunque mostrare i documenti salvati sul telefono
  const [copiaAperta, setCopiaAperta] = useState(false);

  useEffect(() => {
    // memorizzo eventuale provenienza (?ref=nomeaffiliato) per collegarla all'account al momento della registrazione
    const refParam = pulisciRef(new URLSearchParams(window.location.search).get("ref"));
    // senza ?ref provo a capirlo dal sito da cui arriva (articolo di DronEzine, Instagram, Facebook, Google…)
    const ref = refParam || (refSalvato() ? null : provenienzaDaSito());
    if (ref) { try { localStorage.setItem("eyedrones_ref", ref); } catch { /* memoria del browser non disponibile */ } }

    supabase.auth.getSession().then(({ data }) => setSession(data.session));
    const { data: listener } = supabase.auth.onAuthStateChange((evento, s) => {
      if (evento === "PASSWORD_RECOVERY") setRecupero(true);
      setSession(s);
    });
    return () => listener.subscription.unsubscribe();
  }, []);

  if (session === undefined) {
    return (
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "transparent", color: "#8b95a3", fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 13 }}>
        Caricamento...
      </div>
    );
  }

  if (!session) {
    const copia = leggiCopiaControllo();
    if (copiaAperta && copia) {
      return <DocumentiControllo azienda={copia.azienda || { nome: "" }} impianti={[]} soloCopia schermoPienoSubito onSchermoPienoAperto={() => {}} onEsciCopia={() => setCopiaAperta(false)} />;
    }
    return (
      <>
        {copia && (
          <div style={{ position: "sticky", top: 0, zIndex: 900, background: "#13233d", borderBottom: "1px solid #2f5aa8", padding: "10px 16px", display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", fontFamily: "'IBM Plex Sans', sans-serif" }}>
            <span style={{ fontSize: 13, color: "#e7eaee" }}>👮 Sei senza rete o devi rientrare? I tuoi documenti di controllo sono salvati sul telefono.</span>
            <button type="button" onClick={() => setCopiaAperta(true)} style={{ background: "#3d8bfd", color: "#fff", border: "none", borderRadius: 6, padding: "7px 12px", fontSize: 13, fontWeight: 700 }}>Mostra i documenti</button>
          </div>
        )}
        <Accesso />
      </>
    );
  }

  if (recupero) return <NuovaPassword onFatto={() => { setRecupero(false); window.history.replaceState(null, "", window.location.pathname); }} />;

  return <AppShell session={session} />;
}

function AppShell({ session }) {
  // se il telefono chiude e riapre la pagina (succede scegliendo foto o video), si torna dove si era
  const PAGINE_RIPRISTINABILI = ["dashboard", "impianti", "pianificazione", "registro-voli", "documenti-controllo", "impostazioni", "abbonamento", "preventivi", "batterie", "permessi", "attestati", "droni", "suggerimenti", "guide", "impara", "posti", "clienti", "collaboratori", "pagina-pilota"];
  const leggiSessione = (k) => { try { return sessionStorage.getItem(k); } catch (e) { return null; } };
  // link dall'email di avviso (?vai=richieste): apre subito le richieste arrivate dalla pagina pubblica
  const [vaiARichieste] = useState(() => new URLSearchParams(window.location.search).get("vai") === "richieste");
  // scorciatoia dell'icona installata (?vai=controllo): apre subito i documenti a schermo pieno
  const [vaiAControllo] = useState(() => new URLSearchParams(window.location.search).get("vai") === "controllo");
  const [controlloSubito, setControlloSubito] = useState(vaiAControllo);
  const [page, setPageInterna] = useState(() => (vaiARichieste ? "pagina-pilota" : vaiAControllo ? "documenti-controllo" : PAGINE_RIPRISTINABILI.includes(leggiSessione("eyedrones_pagina")) ? leggiSessione("eyedrones_pagina") : "dashboard"));
  useEffect(() => { if (vaiARichieste || vaiAControllo) window.history.replaceState(null, "", window.location.pathname); }, []);
  const [paginaPrecedente, setPaginaPrecedente] = useState(null); // da dove si apre «Suggerimenti», per capire dove c'è un problema
  const setPage = (p) => {
    if (p === "suggerimenti") setPaginaPrecedente((prec) => (page !== "suggerimenti" ? page : prec));
    // ogni pagina entra nella cronologia: la freccia «indietro» del telefono torna alla pagina di prima invece di uscire
    if (p !== page) { try { window.history.pushState({ pagina: p }, ""); } catch (e) { /* niente */ } }
    setPageInterna(p);
    try { sessionStorage.setItem("eyedrones_pagina", p); } catch (e) { /* senza memoria di sessione pazienza */ }
  };
  // guida aperta sopra la pagina (es. «Come si fa a volare qui?» dalla verifica zona): non si perde quello che stavi facendo
  const [guidaSopra, setGuidaSopra] = useState(null);
  const guidaAperta = useRef(false);
  guidaAperta.current = !!guidaSopra;
  const chiudiGuida = () => { if (guidaAperta.current) window.history.back(); };
  useEffect(() => {
    try { window.history.replaceState({ ...(window.history.state || {}), pagina: page }, ""); } catch (e) { /* niente */ }
    const indietro = (e) => {
      if (guidaAperta.current) { setGuidaSopra(null); return; }
      const p = e.state && e.state.pagina;
      if (p && PAGINE_RIPRISTINABILI.concat(["nuova"]).includes(p)) {
        setPageInterna(p);
        try { sessionStorage.setItem("eyedrones_pagina", p); } catch (err) { /* niente */ }
      }
    };
    window.addEventListener("popstate", indietro);
    return () => window.removeEventListener("popstate", indietro);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // avviso quando la pagina è stata riaperta mentre si sceglieva un file
  const [paginaRiaperta, setPaginaRiaperta] = useState(() => {
    const t = Number(leggiSessione("eyedrones_scelta_file") || 0);
    try { sessionStorage.removeItem("eyedrones_scelta_file"); } catch (e) { /* niente */ }
    return t > 0 && Date.now() - t < 15 * 60000;
  });
  useEffect(() => {
    const segna = (e) => { if (e.target && e.target.matches && e.target.matches("input[type=file]")) { try { sessionStorage.setItem("eyedrones_scelta_file", String(Date.now())); } catch (err) { /* niente */ } } };
    const togli = (e) => { if (e.target && e.target.matches && e.target.matches("input[type=file]")) { try { sessionStorage.removeItem("eyedrones_scelta_file"); } catch (err) { /* niente */ } } };
    // se si torna nella pagina senza che sia stata ricaricata (scelta annullata o file scelto), il segno non serve più
    let timer = null;
    const ritorno = () => {
      if (document.visibilityState !== "visible") return;
      clearTimeout(timer);
      timer = setTimeout(() => { try { sessionStorage.removeItem("eyedrones_scelta_file"); } catch (err) { /* niente */ } }, 2500);
    };
    document.addEventListener("click", segna, true);
    document.addEventListener("change", togli, true);
    document.addEventListener("cancel", togli, true);
    window.addEventListener("focus", ritorno);
    document.addEventListener("visibilitychange", ritorno);
    return () => {
      clearTimeout(timer);
      document.removeEventListener("click", segna, true); document.removeEventListener("change", togli, true); document.removeEventListener("cancel", togli, true);
      window.removeEventListener("focus", ritorno); document.removeEventListener("visibilitychange", ritorno);
    };
  }, []);
  const [impiantoAttivo, setImpiantoAttivo] = useState(null);
  const [azienda, setAzienda] = useState({ nome: "EyeDrones", logo: LOGO_EYEDRONES, tariffaBase: 150, tariffaKwp: 0.12, noteLegaliPreventivo: "" });
  const [pianoReale, setPiano] = useState("free");
  // durante il lancio tutti usano le funzioni Pro; la pagina Abbonamento mostra il piano vero
  const piano = lancioInCorso() ? "pro" : pianoReale;
  const [profiloCaricato, setProfiloCaricato] = useState(false);

  const [impianti, setImpianti] = useState([]);
  const [ispezioni, setIspezioni] = useState([]);
  const [anomalieAll, setAnomalieAll] = useState([]);
  const [fotoAll, setFotoAll] = useState([]);
  const [reportLog, setReportLog] = useState([]);
  const [preventivi, setPreventivi] = useState([]);
  const [permessi, setPermessi] = useState([]);
  const [attestati, setAttestati] = useState([]);
  const [droni, setDroni] = useState([]);
  const [moduli, setModuli] = useState(null); // null = non ancora scelto ("ispezioni", "riprese" o entrambi separati da virgola)
  const [obiettivoFormativo, setObiettivoFormativo] = useState("");
  const [voliManuali, setVoliManuali] = useState([]);
  const [nuovoVolo, setNuovoVolo] = useState(false);
  const [vistaVoli, setVistaVoliInterna] = useState(() => (["voli", "galleria", "mappa"].includes(leggiSessione("eyedrones_vista_voli")) ? leggiSessione("eyedrones_vista_voli") : "voli")); // "voli" | "galleria" | "mappa"
  const setVistaVoli = (v) => { setVistaVoliInterna(v); try { sessionStorage.setItem("eyedrones_vista_voli", v); } catch (e) { /* niente */ } };
  const [fileRapidi, setFileRapidi] = useState(null); // file scelti dalla prima pagina, da allegare a un nuovo volo
  const [prefillVolo, setPrefillVolo] = useState(null); // dati di un piano di volo, da precompilare aprendo "Nuovo volo"
  const [pianoDaAprire, setPianoDaAprire] = useState(null); // id di un piano di volo da aprire (dalla Home)
  const [batterie, setBatterie] = useState([]);
  const [eventiVolo, setEventiVolo] = useState([]);
  const [dflightScadenza, setDflightScadenza] = useState(undefined); // undefined = colonna non ancora creata dallo script SQL
  const [richiesteNuove, setRichiesteNuove] = useState(0); // richieste di preventivo arrivate dalla pagina pubblica e non ancora aperte
  const [bozzaPreventivo, setBozzaPreventivo] = useState(null); // richiesta da trasformare in preventivo
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState(null);

  const caricaProfilo = async () => {
    let { data: profilo } = await supabase.from("profili").select("*").eq("user_id", session.user.id).maybeSingle();
    if (!profilo) {
      // la provenienza è salvata anche nell'account alla registrazione: serve quando il link di conferma si apre in un altro browser
      const referral = refSalvato() || pulisciRef(session.user.user_metadata?.ref);
      const { data: nuovo } = await supabase.from("profili").insert({ user_id: session.user.id, referral: referral || null, email: session.user.email }).select().single();
      profilo = nuovo;
    } else if (!profilo.email) {
      await supabase.from("profili").update({ email: session.user.email }).eq("user_id", session.user.id);
    }
    if (profilo) {
      setPiano(profilo.piano || "free");
      setModuli(profilo.moduli || null);
      setObiettivoFormativo(profilo.obiettivo_formativo || "");
      setDflightScadenza("dflight_scadenza" in profilo ? profilo.dflight_scadenza || "" : undefined);
      setAzienda({
        nome: profilo.azienda_nome || "EyeDrones",
        nomeImpostato: !!profilo.azienda_nome,
        logo: profilo.azienda_logo && !profilo.azienda_logo.startsWith(LOGO_PRECEDENTE_PREFISSO) ? profilo.azienda_logo : LOGO_EYEDRONES,
        tariffaBase: profilo.tariffa_base ?? 150,
        tariffaKwp: profilo.tariffa_kwp ?? 0.12,
        noteLegaliPreventivo: profilo.preventivo_note_legali || "",
      });
      salvaCopiaControllo({ azienda: { nome: profilo.azienda_nome || "EyeDrones" } });
    }
    setProfiloCaricato(true);
  };

  const salvaProfiloAzienda = async (nuovaAzienda) => {
    setAzienda(nuovaAzienda);
    await supabase.from("profili").update({
      azienda_nome: nuovaAzienda.nome,
      azienda_logo: nuovaAzienda.logo,
      tariffa_base: nuovaAzienda.tariffaBase,
      tariffa_kwp: nuovaAzienda.tariffaKwp,
      preventivo_note_legali: nuovaAzienda.noteLegaliPreventivo,
    }).eq("user_id", session.user.id);
  };

  const salvaModuli = async (nuovi) => {
    setModuli(nuovi);
    const { error } = await supabase.from("profili").update({ moduli: nuovi }).eq("user_id", session.user.id);
    if (error) alert("Non sono riuscito a salvare la scelta sul tuo account (" + error.message + "). Per ora vale solo finché tieni aperta l'app: controlla di aver eseguito lo script SQL degli aggiornamenti.");
  };

  const salvaObiettivoFormativo = async (valore) => {
    setObiettivoFormativo(valore);
    const { error } = await supabase.from("profili").update({ obiettivo_formativo: valore }).eq("user_id", session.user.id);
    if (error) alert("Non sono riuscito a salvare l'obiettivo sul tuo account (" + error.message + "). Controlla di aver eseguito lo script SQL degli aggiornamenti.");
  };

  // i voli si leggono a parte: se la tabella non esiste ancora, il resto dell'app funziona lo stesso
  const caricaVoli = async () => {
    const { data } = await supabase.from("voli").select("*").order("data", { ascending: false });
    setVoliManuali(data || []);
  };

  // come i voli, anche le batterie si leggono a parte: se la tabella non esiste ancora, il resto dell'app funziona lo stesso
  const caricaEventiVolo = async () => {
    const { data } = await supabase.from("eventi_volo").select("*").order("data_ora", { ascending: false });
    setEventiVolo(data || []);
  };

  const salvaDflightScadenza = async (valore) => {
    setDflightScadenza(valore);
    const { error } = await supabase.from("profili").update({ dflight_scadenza: valore || null }).eq("user_id", session.user.id);
    if (error) alert("Non sono riuscito a salvare la scadenza (" + error.message + "). Controlla di aver eseguito lo script SQL «eventi-dflight.sql».");
  };

  // solo il numero: se la tabella non esiste ancora (script pagina-pilota.sql) resta 0
  const caricaRichiesteNuove = async () => {
    const { count } = await supabase.from("richieste_preventivo").select("id", { count: "exact", head: true }).eq("stato", "nuova");
    setRichiesteNuove(count || 0);
  };

  const [clienti, setClienti] = useState([]);
  const [schedaImpara, setSchedaImpara] = useState("a1a3");
  const [luogoDaPianificare, setLuogoDaPianificare] = useState(null); // da «Posti»: { nome, lat, lon }
  useEffect(() => {
    const ascolta = (e) => {
      const d = e.detail || {};
      if (d.pagina === "impara" && d.sopra && d.scheda === "zona-rossa") { try { window.history.pushState({ ...(window.history.state || {}), guida: true }, ""); } catch (err) { /* niente */ } setGuidaSopra(d.scheda); }
      else if (d.pagina === "impara") { setSchedaImpara(d.scheda || "a1a3"); setPage("impara"); window.scrollTo(0, 0); }
      else if (d.pagina === "permessi" || d.pagina === "nuova") { setGuidaSopra(null); setPage(d.pagina); window.scrollTo(0, 0); }
      else if (d.pagina === "pianificazione") { if (d.luogo) setLuogoDaPianificare(d.luogo); setPage("pianificazione"); window.scrollTo(0, 0); }
    };
    window.addEventListener("eyedrones-vai", ascolta);
    return () => window.removeEventListener("eyedrones-vai", ascolta);
  }, []);
  // frasi per il report scelte sul posto: le salvo anche nell'account, così le ritrovi sul computer
  useEffect(() => {
    const salva = (e) => { supabase.auth.updateUser({ data: { frasi_report: e.detail || null } }).then(() => {}, () => {}); };
    window.addEventListener("eyedrones-frasi-report", salva);
    return () => window.removeEventListener("eyedrones-frasi-report", salva);
  }, []);
  const caricaClienti = async () => {
    const { data, error } = await supabase.from("clienti").select("*").order("nome", { ascending: true });
    setClienti(error ? [] : data || []); // tabella non ancora creata: rubrica vuota
  };

  const caricaBatterie = async () => {
    const { data } = await supabase.from("batterie").select("*").order("created_at", { ascending: true });
    setBatterie(data || []);
  };

  const loadData = async () => {
    setLoading(true);
    setDbError(null);
    try {
      const [{ data: imp, error: e1 }, { data: isp, error: e2 }, { data: ano, error: e3 }, { data: fot, error: e4 }, { data: log, error: e5 }, { data: prev, error: e6 }, { data: perm, error: e7 }, { data: att, error: e8 }, { data: drn, error: e9 }] = await Promise.all([
        supabase.from("impianti").select("*").order("created_at"),
        supabase.from("ispezioni").select("*").order("data", { ascending: false }),
        supabase.from("anomalie").select("*"),
        supabase.from("foto").select("*"),
        supabase.from("report_log").select("*"),
        supabase.from("preventivi").select("*").order("created_at", { ascending: false }),
        supabase.from("permessi").select("*").order("created_at", { ascending: false }),
        supabase.from("attestati").select("*").order("data_scadenza", { ascending: true }),
        supabase.from("droni").select("*").order("created_at", { ascending: false }),
      ]);
      if (e1 || e2 || e3 || e4 || e5 || e6 || e7 || e8 || e9) throw (e1 || e2 || e3 || e4 || e5 || e6 || e7 || e8 || e9);
      setImpianti(imp || []);
      setIspezioni(isp || []);
      setAnomalieAll(ano || []);
      setFotoAll(fot || []);
      setReportLog(log || []);
      setPreventivi(prev || []);
      setPermessi(perm || []);
      setAttestati(att || []);
      setDroni(drn || []);
      salvaCopiaControllo({ attestati: att || [], droni: drn || [], permessi: perm || [] });
    } catch (err) {
      setDbError(err.message || "Errore di connessione al database");
    }
    setLoading(false);
  };

  useEffect(() => { caricaProfilo(); loadData(); caricaVoli(); caricaBatterie(); caricaEventiVolo(); caricaRichiesteNuove(); caricaClienti(); }, []);
  // piani vicini nella copia per i controlli senza rete
  useEffect(() => {
    supabase.from("piani_volo").select("*").gte("data_prevista", dataLocale(-1)).order("data_prevista", { ascending: true }).limit(30)
      .then(({ data, error }) => { if (!error && data) salvaCopiaControllo({ piani: pianiPerCopia(data) }); });
  }, []);

  // quanti report ha gi\u00e0 generato l'utente nel mese corrente (log persistente: non si azzera cancellando impianti/ispezioni)
  const oggi = new Date();
  const reportQuestoMese = reportLog.filter((r) => {
    const d = new Date(r.creato_at);
    return d.getMonth() === oggi.getMonth() && d.getFullYear() === oggi.getFullYear();
  }).length;

  // arricchisco ogni impianto con ultima ispezione e numero anomalie, calcolati dai dati reali
  const impiantiConStat = impianti.map((imp) => {
    const ispezioniImp = ispezioni.filter((i) => i.impianto_id === imp.id);
    const idsIsp = ispezioniImp.map((i) => i.id);
    const anomalieImp = anomalieAll.filter((a) => idsIsp.includes(a.ispezione_id));
    return { ...imp, ultima: ispezioniImp[0] ? formatData(ispezioniImp[0].data) : "Nessuna ispezione", anomalie: anomalieImp.length };
  });

  // l'impianto selezionato è "in diretta": se lo modifichi altrove (es. svuoti il kWp), qui non resta mai una fotografia vecchia
  const impiantoCorrente = impiantoAttivo ? impiantiConStat.find((i) => i.id === impiantoAttivo.id) : null;

  // navigazione: "Foto e video" nel menu è la galleria del registro voli
  const vai = (chiave) => {
    if (chiave === "galleria") { setVistaVoli("galleria"); setPage("registro-voli"); return; }
    if (chiave === "registro-voli") setVistaVoli("voli");
    setPage(chiave);
  };
  const paginaMenu = page === "registro-voli" && vistaVoli === "galleria" ? "galleria" : page;

  const usaIspezioni = !moduli || moduli.includes("ispezioni");
  const usaRiprese = !moduli || moduli.includes("riprese");
  const voliDashboard = [...voliManuali, ...costruisciVoliDaIspezioni(ispezioni, impianti)].sort((a, b) => {
    const da = `${a.data || ""} ${a.ora ? String(a.ora).slice(0, 5) : "00:00"}`;
    const db = `${b.data || ""} ${b.ora ? String(b.ora).slice(0, 5) : "00:00"}`;
    return db.localeCompare(da);
  });

  return (
    <div className="app-shell" style={{ fontFamily: "'IBM Plex Sans', sans-serif", background: "transparent", color: "#e7eaee", minHeight: "100vh", display: "flex", width: "100%" }}>
      <style>{`
        * { box-sizing: border-box; }
        html { scroll-behavior: smooth; }
        button { font-family: inherit; cursor: pointer; transition: filter .12s ease, transform .12s ease, opacity .12s ease; }
        button:not(:disabled):hover { filter: brightness(1.1); }
        button:not(:disabled):active { filter: brightness(0.94); transform: translateY(0.5px); }
        input, select, textarea { transition: border-color .15s ease, background .15s ease; }
        input:focus, select:focus, textarea:focus { outline: none; border-color: #ff8c42 !important; }
        h1, h2, h3 { letter-spacing: -0.012em; }
        ::selection { background: #ff8c4255; }
        ::-webkit-scrollbar { width: 10px; height: 10px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: #333a45; border-radius: 8px; }
        ::-webkit-scrollbar-thumb:hover { background: #454c59; }
        .mono { font-family: 'IBM Plex Mono', monospace; }
        .app-shell { flex-direction: row; }
        .sidebar { width: 220px; flex-direction: column; }
        .sidebar-label { display: inline; }
        .sidebar-brand-label { display: inline; }
        .main-content { padding: 28px 32px; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        .spin { animation: spin 1s linear infinite; }
        .menu-telefono { display: none; }
        .avviso-caricamento { bottom: 24px; }
        .home-azioni { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px; }
        .home-azione { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; background: #1b2028; border: 1px solid #2b313d; border-radius: 14px; padding: 14px 16px; color: #e7eaee; min-height: 74px; transition: border-color .15s, transform .15s, background .15s; }
        .home-azione:hover { border-color: #ff8c4288; background: #1f252e; transform: translateY(-1px); }
        .home-azione-emoji { font-size: 22px; flex: none; width: 44px; height: 44px; border-radius: 12px; display: inline-flex; align-items: center; justify-content: center; }
        .home-azione-titolo { display: block; font-size: 14.5px; font-weight: 700; }
        .home-azione-testo { display: block; font-size: 12px; margin-top: 2px; color: #8b95a3; }
        .home-testata { position: relative; overflow: hidden; border-radius: 18px; border: 1px solid #2b313d; padding: 26px 28px; margin-bottom: 18px; min-height: 170px; background-size: cover; background-position: center; display: flex; align-items: flex-end; }
        /* animazioni leggere della Home: il drone della testata e un'entrata morbida (solo opacità, niente spostamenti) */
        @keyframes ed-vola { 0%, 100% { transform: translateY(0) rotate(0deg); } 50% { transform: translateY(-7px) rotate(-1.2deg); } }
        @keyframes ed-elica { 0%, 100% { transform: scaleX(1); } 50% { transform: scaleX(.45); } }
        @keyframes ed-luce { 0%, 62%, 100% { opacity: 1; } 72% { opacity: .12; } }
        @keyframes ed-scia { to { stroke-dashoffset: -24; } }
        @keyframes ed-stelle { 0%, 100% { opacity: .55; } 50% { opacity: .25; } }
        @keyframes ed-entra { from { opacity: 0; } to { opacity: 1; } }
        .ed-vola { animation: ed-vola 4.5s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
        .ed-elica { animation: ed-elica .16s linear infinite; transform-box: fill-box; transform-origin: center; }
        .ed-elica-b { animation-delay: -.08s; }
        .ed-luce { animation: ed-luce 1.8s ease-in-out infinite; }
        .ed-luce-b { animation-delay: -.9s; }
        .ed-scia { animation: ed-scia 1.5s linear infinite; }
        .ed-stelle { animation: ed-stelle 5s ease-in-out infinite; }
        .home > div > * { animation: ed-entra .45s ease-out both; }
        .home > div > *:nth-child(2) { animation-delay: .06s; } .home > div > *:nth-child(3) { animation-delay: .12s; }
        .home > div > *:nth-child(4) { animation-delay: .18s; } .home > div > *:nth-child(n+5) { animation-delay: .24s; }
        @media (prefers-reduced-motion: reduce) { .ed-vola, .ed-elica, .ed-luce, .ed-scia, .ed-stelle, .home > div > * { animation: none !important; } }
        .home-striscia { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 6px; scrollbar-width: thin; }
        .home-azione .corto { display: none; }
        .home-due { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 14px; align-items: start; }
        @media (max-width: 680px) {
          .app-shell { flex-direction: column; }
          .sidebar { display: none !important; }
          .home { padding: 16px !important; }
          .home-due { grid-template-columns: 1fr; }
          .home-azioni { grid-template-columns: repeat(3, 1fr); gap: 8px; }
          .home-azione { flex-direction: column; justify-content: center; text-align: center; gap: 4px; padding: 10px 6px; min-height: 84px; }
          .home-azione .lungo, .home-azione-testo { display: none !important; }
          .home-azione .corto { display: inline; }
          .home-azione-titolo { font-size: 12.5px; }
          .home-testata { padding: 18px 16px; min-height: 150px; border-radius: 14px; }
          .home-testata h1 { font-size: 24px !important; }
          .menu-telefono { display: contents; }
          .mt-topbar { position: sticky; top: 0; z-index: 800; display: flex; align-items: center; gap: 8px; padding: 10px 16px; padding-top: calc(10px + env(safe-area-inset-top)); background: rgba(18, 21, 26, 0.92); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border-bottom: 1px solid #262b33; }
          .mt-tabbar { position: fixed; left: 0; right: 0; bottom: 0; z-index: 900; display: flex; background: rgba(18, 21, 26, 0.96); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border-top: 1px solid #262b33; padding-bottom: env(safe-area-inset-bottom); }
          .mt-tab { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 8px 2px 7px 2px; background: none; border: none; color: #7c8694; font-size: 10.5px; font-weight: 500; min-height: 56px; justify-content: center; }
          .mt-tab.on { color: #ff8c42; font-weight: 700; }
          .avviso-caricamento { bottom: calc(72px + env(safe-area-inset-bottom)) !important; }
          .mt-overlay { position: fixed; inset: 0; z-index: 950; background: rgba(0, 0, 0, 0.55); display: flex; align-items: flex-end; }
          .mt-sheet { width: 100%; max-height: 82vh; overflow-y: auto; background: #161a20; border-top: 1px solid #2b313d; border-radius: 16px 16px 0 0; padding: 10px 14px calc(16px + env(safe-area-inset-bottom)) 14px; }
          .app-shell > div:last-child { padding-bottom: calc(64px + env(safe-area-inset-bottom)); }
          .main-content { padding: 18px 16px; }
        }
      `}</style>

      <Sidebar page={paginaMenu} setPage={vai} userEmail={session.user.email} piano={piano} reportQuestoMese={reportQuestoMese} attestatiInScadenza={attestati.filter((a) => a.data_scadenza && new Date(a.data_scadenza) < new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)).length} droniInScadenza={droni.filter((d) => d.prossima_manutenzione && new Date(d.prossima_manutenzione) < new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)).length} usaIspezioni={usaIspezioni} batterieAvvisi={batterie.reduce((n, b) => n + avvisiBatteria(b).length, 0)} richiesteNuove={richiesteNuove} onControllo={() => { setControlloSubito(true); setPage("documenti-controllo"); }} />

      <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>
        <AvvisoInstallaApp />
        {paginaRiaperta && (
          <div role="alert" style={{ margin: "12px 16px 0 16px", background: "#2a2416", border: "1px solid #5a4a20", borderRadius: 10, padding: "12px 14px", display: "flex", gap: 10, alignItems: "flex-start" }}>
            <span style={{ fontSize: 18 }}>⚠️</span>
            <div style={{ flex: 1, fontSize: 12.5, color: "#e7eaee", lineHeight: 1.5 }}>
              <strong>Il telefono ha riaperto la pagina mentre sceglievi il file</strong>, quindi la foto o il video non sono stati caricati. Succede quando la memoria è poca. Riprova così:
              <ul style={{ margin: "4px 0 0 0", paddingLeft: 18, color: "#c3cad4" }}>
                <li>scegli il video dalla <strong>Galleria</strong> o da <strong>File</strong>, invece di registrarlo al momento con la fotocamera;</li>
                <li>chiudi le altre app aperte, poi riprova;</li>
                <li>se capita spesso, installa EyeDrones sul telefono (avviso in alto): l'app viene chiusa meno spesso.</li>
              </ul>
            </div>
            <button onClick={() => setPaginaRiaperta(false)} aria-label="Chiudi avviso" style={{ background: "none", border: "none", color: "#8b95a3" }}><X size={16} /></button>
          </div>
        )}
        {dbError && (
          <div style={{ margin: 16, padding: "10px 14px", background: "#2a1616", border: "1px solid #5a2a2a", borderRadius: 8, color: "#ff9c9c", fontSize: 12.5 }}>
            {typeof navigator !== "undefined" && navigator.onLine === false
              ? <>Sei senza rete: i dati si aggiornano quando torna il campo. I documenti di controllo restano disponibili dalla copia salvata sul telefono (👮 Controllo).</>
              : <>Impossibile leggere il database: {dbError}. Controlla di aver eseguito lo script SQL su Supabase.</>}
          </div>
        )}
        {guidaSopra && (
          <div role="dialog" aria-label="Guida zona rossa" style={{ position: "fixed", inset: 0, zIndex: 2500, background: "#0f1216", display: "flex", flexDirection: "column" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", paddingTop: "calc(10px + env(safe-area-inset-top))", borderBottom: "1px solid #262b33", background: "#12151a" }}>
              <button type="button" onClick={chiudiGuida} style={{ background: "#1f2530", border: "1px solid #333a45", color: "#e7eaee", borderRadius: 8, padding: "8px 14px", fontSize: 14, fontWeight: 700, minHeight: 44 }}>← Torna al piano</button>
              <span style={{ fontSize: 14.5, fontWeight: 700, color: "#ffb877" }}>🔴 Zona rossa: cosa serve</span>
            </div>
            <div style={{ flex: 1, overflowY: "auto", padding: "16px 16px 24px", maxWidth: 820, width: "100%", boxSizing: "border-box", margin: "0 auto" }}>
              <Suspense fallback={<p style={{ color: "#8b95a3" }}>Carico la guida…</p>}><GuidaZonaRossa /></Suspense>
              <button type="button" onClick={chiudiGuida} style={{ display: "block", width: "100%", marginTop: 16, background: "linear-gradient(135deg, #ff9d5c, #e0552f)", color: "#161a1f", border: "none", borderRadius: 10, padding: "12px", fontSize: 15, fontWeight: 800, minHeight: 50 }}>← Torna al piano (non si perde niente)</button>
            </div>
          </div>
        )}
        {page === "dashboard" && <Dashboard impianti={impiantiConStat} loading={loading} onOpenImpianto={(i) => { setImpiantoAttivo(i); setPage("impianto"); }} onNuova={() => setPage("nuova")} numIspezioni={ispezioni.length} usaIspezioni={usaIspezioni} usaRiprese={usaRiprese} moduli={moduli} onSalvaModuli={salvaModuli} voli={voliDashboard} attestati={attestati} droni={droni} batterie={batterie} onNav={vai} onNuovoVolo={() => { setVistaVoli("voli"); setNuovoVolo(true); setPage("registro-voli"); }} onAggiungiFile={(files) => { setFileRapidi(files); setVistaVoli("voli"); setNuovoVolo(true); setPage("registro-voli"); }} eventiVolo={eventiVolo} dflightScadenza={dflightScadenza} onApriPiano={(id) => { setPianoDaAprire(id); setPage("pianificazione"); }} onDocumentiPiano={(id) => { setPianoDaAprire(id); setPage("documenti-controllo"); }} onControllo={() => { setControlloSubito(true); setPage("documenti-controllo"); }} preventivi={preventivi} nomeSaluto={azienda.nomeImpostato ? azienda.nome : ""} onRegistraDaPiano={(dati) => { setPrefillVolo(dati); setVistaVoli("voli"); setNuovoVolo(true); setPage("registro-voli"); }} />}
        {page === "impianti" && <ListaImpianti impianti={impiantiConStat} loading={loading} onReload={loadData} onOpenImpianto={(i) => { setImpiantoAttivo(i); setPage("impianto"); }} ispezioni={ispezioni} fotoAll={fotoAll} />}
        {page === "impianto" && impiantoCorrente && <DettaglioImpianto impianto={impiantoCorrente} ispezioni={ispezioni.filter((i) => i.impianto_id === impiantoCorrente.id)} anomalieAll={anomalieAll} fotoAll={fotoAll} azienda={azienda} piano={piano} onBack={() => setPage("impianti")} onReload={loadData} />}
        {page === "nuova" && <NuovaIspezione impianti={impiantiConStat} onSaved={loadData} onDone={() => setPage("dashboard")} azienda={azienda} piano={piano} reportQuestoMese={reportQuestoMese} />}
        {page === "pianificazione" && <PianificazioneVolo azienda={azienda} impianti={impianti} session={session} piano={piano} pianoIniziale={pianoDaAprire} onPianoAperto={() => setPianoDaAprire(null)} luogoIniziale={luogoDaPianificare} onLuogoUsato={() => setLuogoDaPianificare(null)} onVaiRegistroConDati={(dati) => { setPrefillVolo(dati); setVistaVoli("voli"); setNuovoVolo(true); setPage("registro-voli"); }} />}
        {page === "registro-voli" && <RegistroVoli azienda={azienda} droni={droni} ispezioni={ispezioni} impianti={impianti} aprireNuovo={nuovoVolo} onAperto={() => { setNuovoVolo(false); setFileRapidi(null); setPrefillVolo(null); }} onCambiato={caricaVoli} vista={vistaVoli} onVista={setVistaVoli} fileIniziali={fileRapidi} prefillIniziale={prefillVolo} batterie={batterie} onBatterieCambiate={caricaBatterie} piano={piano} onVaiAbbonamento={() => setPage("abbonamento")} eventiVolo={eventiVolo} onEventiCambiati={caricaEventiVolo} />}
        {page === "documenti-controllo" && <DocumentiControllo azienda={azienda} impianti={impianti} usaIspezioni={usaIspezioni} piano={piano} pianoIniziale={pianoDaAprire} onPianoAperto={() => setPianoDaAprire(null)} schermoPienoSubito={controlloSubito} onSchermoPienoAperto={() => setControlloSubito(false)} />}
        {page === "impostazioni" && <Impostazioni userEmail={session.user.email} azienda={azienda} setAzienda={salvaProfiloAzienda} piano={piano} moduli={moduli} onSalvaModuli={salvaModuli} />}
        {page === "abbonamento" && <Abbonamento piano={pianoReale} />}
        {page === "suggerimenti" && <Suggerimenti session={session} paginaPrecedente={paginaPrecedente} />}
        {(page === "impara" || page === "guide") && (
          <Suspense fallback={<LoadingBlock />}>
            <Impara key={page + schedaImpara} schedaIniziale={page === "guide" ? "consigli" : schedaImpara} consigli={<GuideVolo droni={droni} incorporata />} colore={<ColoreVideo />} />
          </Suspense>
        )}
        {page === "collaboratori" && (
          <Suspense fallback={<LoadingBlock />}>
            <Collaboratori supabase={supabase} inputStyle={inputStyle} servizi={SERVIZI_PILOTA} />
          </Suspense>
        )}
        {page === "posti" && (
          <Suspense fallback={<LoadingBlock />}>
            <Posti supabase={supabase} cercaIndirizzo={cercaIndirizzoItalia} voli={voliDashboard} inputStyle={inputStyle}
              onPianifica={(l) => { setLuogoDaPianificare(l); setPage("pianificazione"); window.scrollTo(0, 0); }}
              onZonaRossa={() => vaiA({ pagina: "impara", scheda: "zona-rossa", sopra: true })} />
          </Suspense>
        )}
        {page === "clienti" && <Clienti clienti={clienti} preventivi={preventivi} onCambiati={caricaClienti} onApriPreventivi={() => setPage("preventivi")} />}
        <datalist id="rubrica-clienti">{clienti.map((c) => <option key={c.id} value={c.nome} />)}</datalist>
        {page === "preventivi" && <Preventivi preventivi={preventivi} clienti={clienti} onClientiCambiati={caricaClienti} azienda={azienda} piano={piano} onReload={loadData} onVaiAbbonamento={() => setPage("abbonamento")} bozza={bozzaPreventivo} onBozzaUsata={() => setBozzaPreventivo(null)} />}
        {page === "pagina-pilota" && <LaMiaPagina schedaIniziale={vaiARichieste ? "richieste" : "pagina"} azienda={azienda} attestati={attestati} piano={piano} onRichiesteCambiate={caricaRichiesteNuove} onCreaPreventivo={(r) => { setBozzaPreventivo(r); setPage("preventivi"); }} />}
        {page === "batterie" && <Batterie batterie={batterie} droni={droni} piano={piano} onReload={caricaBatterie} onVaiAbbonamento={() => setPage("abbonamento")} />}
        {page === "permessi" && <Permessi permessi={permessi} impianti={impianti} azienda={azienda} piano={piano} onReload={loadData} droni={droni} emailUtente={session.user.email} />}
        {page === "attestati" && <Attestati attestati={attestati} azienda={azienda} onReload={loadData} obiettivoFormativo={obiettivoFormativo} onSalvaObiettivo={salvaObiettivoFormativo} />}
        {page === "droni" && <Droni droni={droni} azienda={azienda} onReload={loadData} dflightScadenza={dflightScadenza} onSalvaDflightScadenza={salvaDflightScadenza} />}
      </div>
    </div>
  );
}

// --- Pagina di presentazione (prima del login) -----------------------------------------------

// «Primi passi» in Home: le 6 cose che fanno funzionare l'app, si spuntano da sole man mano che le fai
const CHIAVE_PRIMI_PASSI = "eyedrones_primi_passi_chiuso";
function PrimiPassi({ droni, attestati, voli, preventivi, onNav }) {
  const [chiuso, setChiuso] = useState(() => { try { return localStorage.getItem(CHIAVE_PRIMI_PASSI) === "si"; } catch { return false; } });
  const [haPiano, setHaPiano] = useState(null);
  useEffect(() => {
    if (chiuso) return undefined;
    let annullato = false;
    supabase.from("piani_volo").select("id").limit(1)
      .then(({ data, error }) => { if (!annullato) setHaPiano(!error && Array.isArray(data) && data.length > 0); })
      .catch(() => { if (!annullato) setHaPiano(false); });
    return () => { annullato = true; };
  }, [chiuso]);
  if (chiuso) return null;

  const oggi = new Date();
  const validi = (attestati || []).filter((a) => !a.data_scadenza || new Date(a.data_scadenza) >= oggi);
  const haAttestato = validi.some((a) => /A1|A2|A3|STS/i.test(a.tipo || ""));
  const haAssicurazione = validi.some((a) => /assicura/i.test(a.tipo || ""));
  const zoneCaricate = (() => { try { return !!localStorage.getItem("eyedrones_zone_caricate"); } catch { return false; } })();
  const passi = [
    { fatto: true, titolo: "Crea il tuo account" },
    { fatto: (droni || []).length > 0, titolo: "Aggiungi il tuo drone", perche: "così l'app sa le regole della sua classe e fin dove puoi volare", pagina: "droni" },
    { fatto: haAttestato && haAssicurazione, titolo: "Carica attestato e assicurazione", perche: haAttestato && !haAssicurazione ? "manca l'assicurazione: in Italia è obbligatoria" : !haAttestato && haAssicurazione ? "manca l'attestato del pilota" : "se ti fermano per un controllo li mostri con un tocco, anche senza campo", pagina: "attestati" },
    { fatto: zoneCaricate, titolo: "Carica il file zone di D-Flight", perche: "si fa una volta sola: poi scrivi la via e sai subito dove puoi volare", pagina: "pianificazione" },
    { fatto: !!haPiano || (voli || []).length > 0, titolo: "Prepara il tuo primo volo", perche: "meteo, luce, zona, regole e le riprese da fare, tutto in una pagina", pagina: "pianificazione" },
    { fatto: (preventivi || []).length > 0, titolo: "Fai il tuo primo preventivo", perche: "in PDF, con i pacchetti pronti e il prezzo consigliato", pagina: "preventivi" },
  ];
  const fatti = passi.filter((x) => x.fatto).length;
  const tutti = fatti === passi.length;
  const prossimo = passi.find((x) => !x.fatto);
  const chiudi = () => { try { localStorage.setItem(CHIAVE_PRIMI_PASSI, "si"); } catch { /* niente */ } setChiuso(true); };
  if (haPiano === null) return null; // aspetto di sapere se c'è già un piano, così non spunto a scatti

  return (
    <div style={{ position: "relative", background: "linear-gradient(135deg, #16202c, #1b2028)", border: "1px solid #2b4a6a", borderRadius: 12, padding: "14px 16px", marginBottom: 18, maxWidth: 720 }}>
      <button type="button" onClick={chiudi} aria-label="Chiudi i primi passi" style={{ position: "absolute", top: 4, right: 4, width: 40, height: 40, background: "none", border: "none", color: "#8b95a3", fontSize: 18 }}>×</button>
      <div style={{ fontSize: 14.5, fontWeight: 700, color: "#7fb0ff", paddingRight: 32 }}>{tutti ? "🎉 Tutto pronto!" : `🚀 Primi passi con EyeDrones · ${fatti} di ${passi.length}`}</div>
      <div style={{ height: 6, background: "#262b33", borderRadius: 3, margin: "8px 0 10px 0", overflow: "hidden" }}>
        <div style={{ width: `${Math.round((fatti / passi.length) * 100)}%`, height: "100%", background: tutti ? "#4ade80" : "#3d8bfd", transition: "width .4s" }} />
      </div>
      {tutti ? (
        <div style={{ fontSize: 13, color: "#c3cad4" }}>
          Hai fatto tutto: l'app è pronta per i tuoi voli. Se ti serve una mano, in <strong>Impara</strong> trovi regole, manovre e consigli.
          <div><button type="button" onClick={chiudi} style={{ marginTop: 10, background: "#4ade80", color: "#12151a", border: "none", borderRadius: 6, padding: "8px 16px", minHeight: 40, fontSize: 13, fontWeight: 700 }}>Perfetto, chiudi</button></div>
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
          {passi.map((x) => {
            const attivo = x === prossimo;
            const riga = (
              <>
                <span style={{ width: 22, height: 22, flex: "none", borderRadius: "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, background: x.fatto ? "#4ade80" : "transparent", color: x.fatto ? "#12151a" : "#8b95a3", border: x.fatto ? "none" : `1.5px solid ${attivo ? "#3d8bfd" : "#4a505a"}` }}>{x.fatto ? "✓" : ""}</span>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ display: "block", fontSize: 13.5, fontWeight: attivo ? 700 : 500, color: x.fatto ? "#6b7480" : "#e7eaee", textDecoration: x.fatto ? "line-through" : "none" }}>{x.titolo}</span>
                  {attivo && x.perche && <span style={{ display: "block", fontSize: 12, color: "#aab3bf", marginTop: 2, lineHeight: 1.4 }}>{x.perche}</span>}
                </span>
                {!x.fatto && <span style={{ color: attivo ? "#3d8bfd" : "#6b7480", fontSize: attivo ? 12.5 : 14, fontWeight: 600, whiteSpace: "nowrap" }}>{attivo ? "Inizia ›" : "›"}</span>}
              </>
            );
            const stile = { display: "flex", gap: 10, alignItems: attivo ? "flex-start" : "center", textAlign: "left", padding: attivo ? "8px 10px" : "6px 10px", margin: "0 -10px", borderRadius: 8, background: attivo ? "#3d8bfd14" : "none", border: "none", color: "#e7eaee", minHeight: 40 };
            return x.fatto || !x.pagina
              ? <div key={x.titolo} style={stile}>{riga}</div>
              : <button key={x.titolo} type="button" onClick={() => onNav(x.pagina)} style={stile}>{riga}</button>;
          })}
        </div>
      )}
    </div>
  );
}

