// avviso "Installa l'app": su Android usa il pulsante di sistema, su iPhone spiega i passaggi di Safari.
// sparisce se l'app è già installata; "Non ora" lo nasconde per 30 giorni (solo su questo dispositivo)
const CHIAVE_INSTALLA_NASCOSTO = "eyedrones_installa_nascosto_fino";

function AvvisoInstallaApp() {
  const giaInstallata = () => window.matchMedia?.("(display-mode: standalone)").matches || window.navigator.standalone === true;
  const suIphone = /iphone|ipad|ipod/i.test(window.navigator.userAgent) || (window.navigator.platform === "MacIntel" && window.navigator.maxTouchPoints > 1);
  const nascostoPerOra = () => {
    try { return Number(localStorage.getItem(CHIAVE_INSTALLA_NASCOSTO) || 0) > Date.now(); } catch (e) { return false; }
  };
  const [evento, setEvento] = useState(() => window.__eventoInstallazione || null);
  const [visibile, setVisibile] = useState(() => !giaInstallata() && !nascostoPerOra());
  const [passiIphone, setPassiIphone] = useState(false);

  useEffect(() => {
    const suInstallabile = () => setEvento(window.__eventoInstallazione || null);
    const suInstallata = () => { window.__eventoInstallazione = null; setVisibile(false); };
    window.addEventListener("eyedrones-installabile", suInstallabile);
    window.addEventListener("appinstalled", suInstallata);
    return () => {
      window.removeEventListener("eyedrones-installabile", suInstallabile);
      window.removeEventListener("appinstalled", suInstallata);
    };
  }, []);

  // su Android/Chrome compare solo quando il browser dice che si può installare; su iPhone sempre (lì non c'è l'evento)
  if (!visibile || (!evento && !suIphone)) return null;

  const nonOra = () => {
    try { localStorage.setItem(CHIAVE_INSTALLA_NASCOSTO, String(Date.now() + 30 * 86400000)); } catch (e) { /* senza memoria: si nasconde solo per ora */ }
    setVisibile(false);
  };
  const installa = async () => {
    if (!evento) { setPassiIphone(true); return; }
    evento.prompt();
    const scelta = await evento.userChoice.catch(() => null);
    window.__eventoInstallazione = null;
    setEvento(null);
    if (scelta && scelta.outcome === "accepted") setVisibile(false);
  };

  return (
    <div style={{ margin: "12px 16px 0 16px", background: "linear-gradient(135deg, rgba(126, 58, 242, 0.18), rgba(255, 140, 66, 0.14)), #1b2028", border: "1px solid #ff8c4255", borderRadius: 10, padding: "12px 14px", display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
      <img src="/icon-192.png" alt="" style={{ width: 40, height: 40, borderRadius: 10, flexShrink: 0 }} />
      <div style={{ flex: 1, minWidth: 180 }}>
        <div style={{ fontSize: 13.5, fontWeight: 700 }}>Installa EyeDrones sul telefono</div>
        {!passiIphone ? (
          <div style={{ fontSize: 12, color: "#aab3bf", marginTop: 2 }}>Si apre con un tocco dalla schermata Home, a schermo intero, come un'app vera. Gratis, niente store.</div>
        ) : (
          <ol style={{ fontSize: 12, color: "#c3cad4", margin: "4px 0 0 0", paddingLeft: 18, lineHeight: 1.6 }}>
            <li>Apri questa pagina con <strong>Safari</strong></li>
            <li>Tocca <strong>Condividi</strong> (il quadrato con la freccia in su ⬆️)</li>
            <li>Scegli <strong>«Aggiungi alla schermata Home»</strong>, poi <strong>Aggiungi</strong></li>
          </ol>
        )}
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        {!passiIphone && <button onClick={installa} style={{ background: "linear-gradient(135deg, #ff9d5c, #e0552f)", color: "#161a1f", border: "none", borderRadius: 6, padding: "8px 14px", fontSize: 13, fontWeight: 700 }}>Installa</button>}
        <button onClick={nonOra} style={{ background: "none", border: "1px solid #333a45", color: "#8b95a3", borderRadius: 6, padding: "8px 12px", fontSize: 12.5 }}>{passiIphone ? "Fatto" : "Non ora"}</button>
      </div>
    </div>
  );
}

// menu per il telefono: barra fissa in basso con le 5 voci principali, il resto nel pannello "Altro"
function MenuTelefono({ items, page, setPage, userEmail, piano, usaIspezioni, avvisi, onControllo }) {
  const [altroAperto, setAltroAperto] = useState(false);
  const principali = [
    { key: "dashboard", label: "Home", icon: LayoutDashboard },
    usaIspezioni ? { key: "impianti", label: "Impianti", icon: Sun } : { key: "galleria", label: "Galleria", icon: Camera },
    { key: "registro-voli", label: "Registro", icon: BookOpen },
    { key: "pianificazione", label: "Pianifica", icon: CalendarDays },
  ];
  const chiaviPrincipali = principali.map((p) => p.key);
  const attivo = (key) => page === key || (page === "impianto" && key === "impianti");
  const altroAttivo = !chiaviPrincipali.some(attivo) && page !== "impianto";
  const totaleAvvisi = Object.values(avvisi).reduce((s, n) => s + (n || 0), 0);
  const titoloPagina = (items.find((it) => it.key === page) || {}).label || (page === "impianto" ? "Impianto" : "");

  useEffect(() => {
    if (!altroAperto) return;
    const chiudi = (e) => e.key === "Escape" && setAltroAperto(false);
    window.addEventListener("keydown", chiudi);
    return () => window.removeEventListener("keydown", chiudi);
  }, [altroAperto]);

  const scegli = (key) => { setAltroAperto(false); setPage(key); window.scrollTo(0, 0); };

  const bollino = (n) => n > 0 && (
    <span style={{ fontSize: 10, fontWeight: 700, background: "#ff4d4d", color: "#fff", borderRadius: 10, padding: "1px 6px", marginLeft: "auto" }}>{n}</span>
  );

  return (
    <div className="menu-telefono">
      <header className="mt-topbar">
        <img src={LOGO_EYEDRONES} alt="" style={{ width: 28, height: 28 }} />
        <span style={{ fontWeight: 700, fontSize: 15 }}>EyeDrones</span>
        {titoloPagina && titoloPagina !== "Panoramica" && <span style={{ color: "#6b7480", fontSize: 13, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>· {titoloPagina}</span>}
        {onControllo && page !== "dashboard" && (
          <button type="button" onClick={() => { setAltroAperto(false); onControllo(); window.scrollTo(0, 0); }} aria-label="Controllo: mostra i documenti" title="Controllo: mostra i documenti" style={{ marginLeft: "auto", flexShrink: 0, display: "flex", alignItems: "center", gap: 4, background: "#13233d", border: "1px solid #2f5aa8", color: "#e7eaee", borderRadius: 6, padding: "3px 8px", fontSize: 12, fontWeight: 700 }}>👮 Controllo</button>
        )}
        <span style={{ marginLeft: onControllo && page !== "dashboard" ? 0 : "auto", flexShrink: 0, fontSize: 10.5, fontWeight: 700, padding: "2px 7px", borderRadius: 4, background: piano === "pro" ? "#1d3a2a" : piano === "pilota" ? "#16263d" : "#2a2416", color: COLORE_PIANO[piano] || "#f5b942" }}>{(NOME_PIANO[piano] || "Free").toUpperCase()}</span>
      </header>

      <nav className="mt-tabbar" aria-label="Menu principale">
        {principali.map((it) => {
          const Icon = it.icon;
          const on = attivo(it.key);
          return (
            <button key={it.key} onClick={() => scegli(it.key)} className={`mt-tab${on ? " on" : ""}`} aria-current={on ? "page" : undefined}>
              <Icon size={21} strokeWidth={on ? 2.4 : 2} />
              <span>{it.label}</span>
            </button>
          );
        })}
        <button onClick={() => setAltroAperto(true)} className={`mt-tab${altroAttivo || altroAperto ? " on" : ""}`} aria-expanded={altroAperto}>
          <span style={{ position: "relative", display: "inline-flex" }}>
            <MoreHorizontal size={21} strokeWidth={2} />
            {totaleAvvisi > 0 && <span style={{ position: "absolute", top: -2, right: -4, width: 8, height: 8, borderRadius: "50%", background: "#ff4d4d" }} />}
          </span>
          <span>Altro</span>
        </button>
      </nav>

      {altroAperto && (
        <div className="mt-overlay" onClick={() => setAltroAperto(false)}>
          <div className="mt-sheet" onClick={(e) => e.stopPropagation()} role="dialog" aria-label="Altre sezioni">
            <div style={{ width: 40, height: 4, borderRadius: 2, background: "#333a45", margin: "0 auto 10px auto" }} />
            {items.filter((it) => it.intestazione || !chiaviPrincipali.includes(it.key)).map((it, idx, arr) => {
              if (it.intestazione) {
                const prossima = arr[idx + 1];
                if (!prossima || prossima.intestazione) return null; // intestazione rimasta senza voci
                return <div key={"h-" + it.intestazione} style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: "0.07em", textTransform: "uppercase", color: "#5b6572", padding: "12px 6px 4px 6px" }}>{it.intestazione}</div>;
              }
              const Icon = it.icon;
              const stile = { display: "flex", alignItems: "center", gap: 12, width: "100%", padding: "11px 8px", borderRadius: 8, background: page === it.key ? "#1f2530" : "transparent", border: "none", color: page === it.key ? "#fff" : "#c3cad4", fontSize: 14.5, textAlign: "left", textDecoration: "none" };
              if (it.esterno) {
                return <a key={it.key} href={it.esterno} target="_blank" rel="noreferrer" style={stile}><Icon size={18} /> {it.label} <span style={{ marginLeft: "auto", color: "#6b7480", fontSize: 12 }}>↗</span></a>;
              }
              return (
                <button key={it.key} onClick={() => scegli(it.key)} style={stile}>
                  <Icon size={18} /> {it.label}
                  {it.key === "preventivi" && piano !== "pro" && <span style={{ marginLeft: "auto", fontSize: 12 }}>🔒</span>}
                  {bollino(avvisi[it.key])}
                </button>
              );
            })}
            <div style={{ borderTop: "1px solid #262b33", marginTop: 10, paddingTop: 12 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
                <span style={{ fontSize: 12, color: "#6b7480", flex: 1, minWidth: 0, wordBreak: "break-all" }}>Accesso con {userEmail}</span>
                <a href={`mailto:${SUPPORT_EMAIL}`} style={{ fontSize: 13, color: "#3d8bfd", textDecoration: "none" }}>Assistenza</a>
              </div>
              <button onClick={esciDallAccount} style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, width: "100%", background: "#2a1616", border: "1px solid #5a2a2a", color: "#ff9c9c", borderRadius: 8, padding: "12px", fontSize: 14.5, fontWeight: 600 }}>
                <LogOut size={16} /> Esci dall'account
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// --- Dashboard -----------------------------------------------------------

function TitoloSezione({ emoji, titolo, azione }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap", margin: "0 0 12px 0", paddingBottom: 8, borderBottom: "1px solid #262b33" }}>
      <h2 style={{ fontSize: 15, fontWeight: 700, margin: 0, display: "flex", alignItems: "center", gap: 8 }}><span>{emoji}</span>{titolo}</h2>
      {azione}
    </div>
  );
}

// scelta di cosa fa il pilota con il drone: decide quali sezioni vedere nel menu e nella prima pagina
function SelettoreModuli({ moduli, onSave, testoBottone = "Conferma" }) {
  const daModuli = (m) => ({ ispezioni: !m || m.includes("ispezioni"), riprese: !m || m.includes("riprese") });
  const [sel, setSel] = useState(daModuli(moduli));
  const [salvando, setSalvando] = useState(false);
  const [salvato, setSalvato] = useState(false);
  useEffect(() => { setSel(daModuli(moduli)); }, [moduli]);
  const nessuno = !sel.ispezioni && !sel.riprese;

  const salva = async () => {
    if (nessuno) return;
    setSalvando(true);
    await onSave([sel.ispezioni ? "ispezioni" : null, sel.riprese ? "riprese" : null].filter(Boolean).join(","));
    setSalvando(false);
    setSalvato(true);
    setTimeout(() => setSalvato(false), 2500);
  };

  const opzione = (chiave, emoji, titolo, testo) => (
    <button
      type="button"
      onClick={() => setSel({ ...sel, [chiave]: !sel[chiave] })}
      style={{ textAlign: "left", flex: 1, minWidth: 230, background: sel[chiave] ? "#241d16" : "#161a1f", border: sel[chiave] ? "1px solid #ff8c42" : "1px solid #333a45", borderRadius: 8, padding: "12px 14px", color: "#e7eaee" }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, fontWeight: 600 }}>
        <span style={{ fontSize: 18 }}>{emoji}</span>{titolo}
        <span style={{ marginLeft: "auto", color: sel[chiave] ? "#ff8c42" : "#4a505a", fontSize: 15 }}>{sel[chiave] ? "✓" : "○"}</span>
      </div>
      <div style={{ fontSize: 11.5, color: "#8b95a3", marginTop: 4, lineHeight: 1.4 }}>{testo}</div>
    </button>
  );

  return (
    <div>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
        {opzione("ispezioni", "🔍", "Ispezioni tecniche", "Fotovoltaico, edifici, danni, impianti elettrici: impianti, report con foto e anomalie, pianificazione dei voli.")}
        {opzione("riprese", "🎬", "Video, foto e FPV", "Registro voli con galleria di foto e video, per chi vola per riprese, lavoro o passione.")}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 12, flexWrap: "wrap" }}>
        <button type="button" onClick={salva} disabled={nessuno || salvando} style={{ background: nessuno ? "#333a45" : "#ff8c42", color: nessuno ? "#6b7480" : "#161a1f", border: "none", padding: "8px 18px", borderRadius: 6, fontWeight: 600, fontSize: 13 }}>
          {salvando ? "Salvataggio..." : testoBottone}
        </button>
        {nessuno && <span style={{ fontSize: 11.5, color: "#f5b942" }}>Scegline almeno una.</span>}
        {salvato && <span style={{ fontSize: 11.5, color: "#4ade80" }}>✓ Salvato</span>}
      </div>
    </div>
  );
}

// avviso in Home durante il lancio (si può chiudere: resta chiuso su questo dispositivo)
function AvvisoLancio({ onScopri }) {
  const [chiuso, setChiuso] = useState(() => { try { return localStorage.getItem("eyedrones_lancio_chiuso") === LANCIO.fino; } catch (e) { return false; } });
  if (chiuso) return null;
  const chiudi = () => { setChiuso(true); try { localStorage.setItem("eyedrones_lancio_chiuso", LANCIO.fino); } catch (e) { /* solo comodità */ } };
  return (
    <div style={{ display: "flex", gap: 12, alignItems: "flex-start", background: "linear-gradient(135deg, rgba(255,140,66,0.14), rgba(126,58,242,0.12)), #1b2028", border: "1px solid #4a2f16", borderRadius: 10, padding: "12px 14px", marginBottom: 22, maxWidth: 720 }}>
      <span style={{ fontSize: 22 }}>🚀</span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 13.5, fontWeight: 700 }}>EyeDrones è in lancio: tutte le funzioni Pro sono gratis fino al {fineLancio()}</div>
        <div style={{ fontSize: 12.5, color: "#c3cad4", marginTop: 3 }}>Sei tra i fondatori: quando partiranno gli abbonamenti avrai il <strong>primo anno a metà prezzo</strong>, con Pro a meno di {euro(Math.ceil(prezzoFondatori(PREZZI_PIANO.pro.anno) / 12))} al mese.</div>
        <button type="button" onClick={onScopri} style={{ marginTop: 8, background: "none", border: "1px solid #ff8c4288", color: "#ffb877", borderRadius: 6, padding: "5px 10px", fontSize: 12 }}>Vedi i prezzi fondatori</button>
      </div>
      <button type="button" onClick={chiudi} aria-label="Chiudi avviso" style={{ background: "none", border: "none", color: "#8b95a3", fontSize: 16, lineHeight: 1 }}>×</button>
    </div>
  );
}

// data di oggi nel fuso del telefono (toISOString darebbe quella UTC: dopo mezzanotte sarebbe ancora "ieri")
const dataLocale = (giorniDopo = 0) => {
  const d = new Date(Date.now() + giorniDopo * 86400000);
  return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
};

// --- Home: il prossimo volo pianificato, con meteo, zona e cosa manca --------------------------------------------
function ProssimoVolo({ droni, batterie, onApriPiano, onDocumenti, onRegistra }) {
  const [piani, setPiani] = useState(null);
  const [meteo, setMeteo] = useState(null); // null = in caricamento, { errore } se non disponibile
  const oggi = dataLocale(), domani = dataLocale(1), fra14 = dataLocale(14);

  useEffect(() => {
    supabase.from("piani_volo").select("*").gte("data_prevista", oggi).lte("data_prevista", fra14).order("data_prevista", { ascending: true }).limit(6)
      .then(({ data }) => setPiani((data || []).filter((x) => !x.checklist_stato?.fatto).sort((a, b) => `${a.data_prevista} ${a.ora_prevista || "99"}`.localeCompare(`${b.data_prevista} ${b.ora_prevista || "99"}`))));
  }, []);

  const p = piani && piani[0] && (piani[0].data_prevista === oggi || piani[0].data_prevista === domani) ? piani[0] : null;
  const zona = p?.checklist_stato?.zona || null;
  const punto = p ? leggiCoordinate(zona?.punto) || leggiCoordinate(p.luogo_coordinate) : null;

  useEffect(() => {
    if (!p) return;
    let annullato = false;
    (async () => {
      try {
        let dove = punto ? { lat: punto.lat, lon: punto.lon, nome: p.impianto_nome } : null;
        if (!dove) {
          const trovato = await cercaIndirizzoItalia(p.impianto_nome);
          dove = trovato ? { lat: trovato.lat, lon: trovato.lon, nome: p.impianto_nome } : p.impianto_nome;
        }
        const m = await recuperaMeteo(dove);
        if (!annullato) setMeteo(m);
      } catch (e) {
        if (!annullato) setMeteo({ errore: true });
      }
    })();
    return () => { annullato = true; };
  }, [p && p.id]);

  if (!piani || piani.length === 0) return null;
  const altri = piani.filter((x) => x !== p).slice(0, 3);
  const giorno = (d) => (d === oggi ? "Oggi" : d === domani ? "Domani" : new Date(`${d}T12:00:00`).toLocaleDateString("it-IT", { weekday: "short", day: "numeric", month: "short" }));
  const ora = (x) => (x.ora_prevista ? String(x.ora_prevista).slice(0, 5) : null);

  const elencoAltri = altri.length > 0 && (
    <div style={{ marginTop: p ? 10 : 0, display: "flex", flexDirection: "column", gap: 4 }}>
      {!p && <TitoloSezione emoji="🗓️" titolo="Prossimi voli" />}
      {altri.map((x) => (
        <button key={x.id} onClick={() => onApriPiano(x.id)} style={{ textAlign: "left", background: "#1b2028", border: "1px solid #2b313d", borderRadius: 8, padding: "8px 12px", color: "#c3cad4", fontSize: 12.5 }}>
          🗓️ <strong style={{ color: "#e7eaee" }}>{giorno(x.data_prevista)}{ora(x) ? ` alle ${ora(x)}` : ""}</strong> · {x.impianto_nome}{x.tipo_ispezione ? ` · ${ETICHETTE_TIPO_PIANO[x.tipo_ispezione] || x.tipo_ispezione}` : ""}
        </button>
      ))}
    </div>
  );
  if (!p) return <section style={{ marginBottom: 18 }}>{elencoAltri}</section>;

  const drone = (droni || []).find((d) => d.id === p.drone_id) || null;
  const limite = Number(drone?.vento_max_kmh) > 0 ? Number(drone.vento_max_kmh) : 30;
  const oraP = ora(p);
  const hOra = oraP ? Number(oraP.slice(0, 2)) : null;
  const ore = meteo && !meteo.errore ? (meteo.orari || []).filter((o) => o.data === p.data_prevista && (hOra == null ? o.ora >= 7 && o.ora <= 20 : Math.abs(o.ora - hOra) <= 2)) : [];
  const allOra = ore.find((o) => o.ora === hOra);
  const luce = meteo && !meteo.errore && meteo.lat != null ? calcolaLuce(p.data_prevista, meteo.lat, meteo.lon) : null;
  const oraLuogo = (d) => formattaOraLuogo(d, meteo?.fusoOrario);
  const riprese = ["video", "foto", "fpv"].includes(p.tipo_ispezione);
  const termografia = ["fotovoltaico", "edifici"].includes(p.tipo_ispezione);
  // volo di oggi con l'ora già passata da più di un'ora: non ha senso dire «condizioni buone alle 10:30» alle 19
  const adesso = new Date();
  const passato = p.data_prevista === oggi && hOra != null && adesso.getHours() * 60 + adesso.getMinutes() > (hOra + 1) * 60 + Number(oraP.slice(3, 5) || 0);
  // «Fatto»: lo segno nel piano, così dalla Home sparisce, e apro il registro già compilato
  const segnaFatto = () => {
    supabase.from("piani_volo").update({ checklist_stato: { ...(p.checklist_stato || {}), fatto: true } }).eq("id", p.id).then(() => {}, () => {});
    setPiani((l) => (l || []).filter((x) => x.id !== p.id));
    onRegistra(datiRegistro());
  };
  // riprese o foto spuntate sul posto: le porto nelle note del volo, così a casa sai l'ordine per il montaggio o il report
  const fatteSulPosto = (() => {
    const girate = (() => { try { const l = JSON.parse(localStorage.getItem(`eyedrones_girate_${p.id}`) || "null"); if (Array.isArray(l)) return l; } catch { /* niente */ } return p.checklist_stato?.girate || []; })();
    const nomi = Array.isArray(p.checklist_stato?.scene)
      ? p.checklist_stato.scene.filter((s) => girate.includes(s.id)).map((s) => s.titolo || (TUTTE_MANOVRE().find((m) => m.id === s.manovra) || {}).nome || "Scena")
      : (p.checklist_stato?.manovre || []).filter((id) => girate.includes(id)).map((id) => TUTTE_MANOVRE().find((m) => m.id === id)).filter(Boolean).map((m) => m.nome.replace(/ \(.*\)$/, ""));
    if (nomi.length === 0) return "";
    return TIPI_ISPEZIONE.includes(p.tipo_ispezione) ? `Foto fatte: ${nomi.join(", ")}` : `Ordine per il montaggio: ${nomi.join(" → ")}`;
  })();
  const datiRegistro = () => ({
    ...(fatteSulPosto ? { note: fatteSulPosto } : {}),
    data: p.data_prevista,
    ...(oraP ? { ora: oraP } : {}),
    luogo: p.impianto_nome || "",
    drone_id: p.drone_id || "",
    tipo_attivita: MAPPA_TIPO_PIANO_A_REGISTRO[p.tipo_ispezione] || "altro",
    ...(punto ? { coordinate_gps: `${punto.lat.toFixed(5)}, ${punto.lon.toFixed(5)}` } : {}),
  });

  const voci = p.checklist_stato?.voci || [];
  const spuntate = voci.filter((_, i) => (p.checklist_stato?.spuntati || {})[i]).length;
  const mancanze = [
    voci.length > 0 && spuntate < voci.length ? `Checklist ${spuntate} di ${voci.length}` : null,
    !p.dflight_screenshot_url ? "Screenshot D-Flight non caricato" : null,
    !zona ? "Zona di volo non controllata" : null,
    !p.drone_id ? "Drone non scelto" : null,
    ...(batterie || []).filter((b) => drone && b.drone_id === drone.id).flatMap((b) => avvisiBatteria(b).map((a) => `${b.nome}: ${a.testo}`)),
  ].filter(Boolean);

  const libera = zona && zona.altezzaLibera;
  const vicinoZona = zona && zona.vicino && zona.vicino.altezza < (libera ?? 120) ? zona.vicino : null;
  const testoZona = !zona ? null : vicinoZona ? ["#f5b942", `A ${vicinoZona.distanza} m c'è una zona ${vicinoZona.altezza > 0 ? `con limite di ${vicinoZona.altezza} m` : "con autorizzazione"}: se ci entri, ${vicinoZona.altezza > 0 ? `resta sotto i ${vicinoZona.altezza} m` : "serve il permesso"}`]
    : !zona.zone || zona.zone.length === 0 ? ["#4ade80", "Nessuna zona UAS: fino a 120 m"]
    : libera >= 120 ? ["#4ade80", "Fino a 120 m con le condizioni della zona"]
    : libera > 0 ? ["#f5b942", `Massimo ${libera} m senza autorizzazione`] : ["#ff8c42", "Serve autorizzazione già da terra"];
  const btn = (primario) => ({ background: primario ? "linear-gradient(135deg, #ff9d5c, #e0552f)" : "#1f2530", color: primario ? "#161a1f" : "#e7eaee", border: primario ? "none" : "1px solid #333a45", borderRadius: 6, padding: "8px 12px", fontSize: 12.5, fontWeight: 600 });

  // ora passata: scheda piccola, solo «l'hai fatto?», senza meteo e consigli che ormai non servono
  if (passato) {
    return (
      <section style={{ marginBottom: 18 }}>
        <div style={{ background: "#1b2028", border: "1px solid #2b313d", borderRadius: 14, padding: 16, display: "flex", gap: 14, alignItems: "center", flexWrap: "wrap" }}>
          <span style={{ fontSize: 22, width: 44, height: 44, borderRadius: 12, background: "#4ade8022", display: "inline-flex", alignItems: "center", justifyContent: "center", flex: "none" }}>✈️</span>
          <div style={{ flex: "1 1 220px", minWidth: 0 }}>
            <div style={{ fontSize: 11.5, color: "#8b95a3", fontWeight: 700, letterSpacing: "0.04em", textTransform: "uppercase" }}>Volo di oggi · {oraP}</div>
            <div style={{ fontSize: 16, fontWeight: 700, marginTop: 2 }}>{p.impianto_nome}{(ETICHETTE_TIPO_PIANO[p.tipo_ispezione] || p.tipo_ispezione) && <span style={{ fontSize: 12.5, color: "#8b95a3", fontWeight: 500 }}> · {ETICHETTE_TIPO_PIANO[p.tipo_ispezione] || p.tipo_ispezione}</span>}</div>
            <div style={{ fontSize: 12.5, color: "#c3cad4", marginTop: 3 }}>Com'è andato? Registralo con un tocco, oppure sposta data e ora se l'hai rimandato.</div>
          </div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            <button type="button" onClick={segnaFatto} style={btn(true)}>✅ Fatto: registralo</button>
            <button type="button" onClick={() => onApriPiano(p.id)} style={btn(false)}>🗓️ Sposta</button>
          </div>
        </div>
        {elencoAltri}
      </section>
    );
  }

  return (
    <section style={{ marginBottom: 18 }}>
      <div style={{ background: "linear-gradient(135deg, #1d2633, #1b2028)", border: "1px solid #3d8bfd66", borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11.5, color: "#7fb0ff", fontWeight: 700, letterSpacing: "0.04em", textTransform: "uppercase" }}>✈️ Il tuo prossimo volo</div>
        <div style={{ fontSize: 18, fontWeight: 700, marginTop: 4 }}>{giorno(p.data_prevista)}{oraP ? ` alle ${oraP}` : ""} · {p.impianto_nome}</div>
        <div style={{ fontSize: 12.5, color: "#8b95a3", marginTop: 2 }}>{[ETICHETTE_TIPO_PIANO[p.tipo_ispezione] || p.tipo_ispezione, drone ? `${drone.nome}${drone.marcatura_classe ? ` (${drone.marcatura_classe})` : ""}` : null].filter(Boolean).join(" · ")}</div>

        <div style={{ marginTop: 12 }}>
          {meteo === null ? <p style={{ fontSize: 12, color: "#8b95a3", margin: 0 }}>Carico il meteo…</p>
            : meteo.errore || ore.length === 0 ? <p style={{ fontSize: 12, color: "#8b95a3", margin: 0 }}>Meteo non disponibile per questo luogo: aprilo da «Apri il piano».</p>
            : (
              <>
                {allOra && (
                  <div style={{ fontSize: 13, fontWeight: 700, color: COLORE_SEMAFORO[valutaOra(allOra, limite)], marginBottom: 6 }}>
                    {(termografia
                      ? { verde: "✓ Vento e pioggia ok", giallo: "⚠ Vento al limite", rosso: "✗ Vento o pioggia sfavorevoli", grigio: "Meteo incompleto" }
                      : { verde: "✓ Condizioni buone", giallo: "⚠ Condizioni al limite", rosso: "✗ Condizioni sfavorevoli", grigio: "Meteo incompleto" })[valutaOra(allOra, limite)]} alle {oraP}: vento {Math.round(allOra.vento)} km/h, raffiche {Math.round(allOra.raffiche)}, pioggia {allOra.probPioggia ?? "—"}%
                  </div>
                )}
                <div style={{ display: "flex", gap: 4, overflowX: "auto", paddingBottom: 2 }}>
                  {ore.map((o) => {
                    const s = valutaOra(o, limite);
                    return (
                      <div key={o.ora} style={{ flex: "0 0 auto", width: 50, textAlign: "center", background: COLORE_SEMAFORO[s] + "1f", border: o.ora === hOra ? "2px solid #ff8c42" : `1px solid ${COLORE_SEMAFORO[s]}66`, borderRadius: 6, padding: "4px 2px", fontSize: 10.5, color: "#c3cad4" }}>
                        <div style={{ fontWeight: 700, color: "#e7eaee" }}>{String(o.ora).padStart(2, "0")}</div>
                        <div style={{ width: 8, height: 8, borderRadius: "50%", background: COLORE_SEMAFORO[s], margin: "3px auto" }} />
                        <div>💨{Math.round(o.vento)}</div>
                        <div style={{ color: "#8b95a3" }}>☔{o.probPioggia ?? "—"}%</div>
                      </div>
                    );
                  })}
                </div>
                <VentoInQuota compatto orari={meteo.orari} data={p.data_prevista} ora={oraP} limite={limite} />
                {riprese && luce && <PrevisioneCielo compatto orari={meteo.orari} data={p.data_prevista} albaMin={minutiDelGiorno(luce.alba, meteo.fusoOrario)} tramontoMin={minutiDelGiorno(luce.tramonto, meteo.fusoOrario)} />}
                {termografia && <SemaforoTermografia tipo={p.tipo_ispezione} orari={meteo.orari} data={p.data_prevista} ora={oraP} />}
                {luce && (
                  <div style={{ fontSize: 12, color: "#c3cad4", marginTop: 6 }}>
                    🌅 {oraLuogo(luce.alba)} · 🌇 {oraLuogo(luce.tramonto)}{riprese && luce.oraOroSera[0] ? <span style={{ color: "#f5b942" }}> · ✨ ora d'oro {oraLuogo(luce.oraOroSera[0])}–{oraLuogo(luce.oraOroSera[1])}</span> : null}
                  </div>
                )}
              </>
            )}
        </div>

        {testoZona && <div style={{ fontSize: 12.5, marginTop: 8, color: testoZona[0], fontWeight: 600 }}>🛡️ {testoZona[1]}</div>}
        {(() => {
          const t = allOra?.temperatura ?? (ore.length ? Math.min(...ore.map((o) => o.temperatura).filter((x) => x != null)) : null);
          const a = avvisoBatterieTemperatura(Number.isFinite(t) ? t : null);
          return a && <div style={{ fontSize: 12.5, marginTop: 6, color: a.colore }}>{a.testo}</div>;
        })()}
        <div style={{ fontSize: 12, color: "#c3cad4", marginTop: 4 }}>📣 Controlla i NOTAM su <a href="https://www.d-flight.it/web-app/" target="_blank" rel="noreferrer" style={{ color: "#3d8bfd" }}>D-Flight ↗</a> prima di partire</div>

        {mancanze.length > 0 && (
          <div style={{ marginTop: 10, background: "#241d16", border: "1px solid #4a2f16", borderRadius: 6, padding: "8px 10px" }}>
            <div style={{ fontSize: 11.5, color: "#ffb877", fontWeight: 700, marginBottom: 2 }}>Prima di partire</div>
            {mancanze.map((m, i) => <div key={i} style={{ fontSize: 12, color: "#e7d3bf" }}>• {m}</div>)}
          </div>
        )}

        {p.checklist_stato?.sopralluogo && (() => {
          const so = p.checklist_stato.sopralluogo;
          const voci = vociSopralluogo(p.tipo_ispezione);
          const mancano = voci.filter((v) => !(so.voci || {})[v.id]);
          return (
            <details style={{ marginTop: 10, background: "#141c26", border: "1px solid #2a4562", borderRadius: 6, padding: "8px 10px" }}>
              <summary style={{ cursor: "pointer", fontSize: 12.5, fontWeight: 700, color: "#7fb0ff" }}>📋 Dal sopralluogo{mancano.length ? ` · ${mancano.length} cose da controllare` : " · tutto controllato"}</summary>
              {(so.orari || []).length > 0 && <div style={{ fontSize: 12, color: "#e7eaee", marginTop: 6 }}>🕐 {so.orari.map((o) => `${o.ora} ${o.evento}`).join(" · ")}</div>}
              {(so.punti || []).map((pt) => (
                <div key={pt.id} style={{ fontSize: 12, color: "#d6dde6", marginTop: 4 }}>
                  {(TIPI_PUNTO[pt.tipo] || TIPI_PUNTO.altro).emoji} {pt.nota || (TIPI_PUNTO[pt.tipo] || TIPI_PUNTO.altro).nome}{" "}
                  <a href={`https://www.google.com/maps?q=${pt.lat},${pt.lon}`} target="_blank" rel="noreferrer" style={{ color: "#7fb0ff" }}>↗</a>
                </div>
              ))}
              {so.note && <div style={{ fontSize: 12, color: "#d6dde6", marginTop: 6, whiteSpace: "pre-wrap" }}>📝 {so.note}</div>}
              {mancano.length > 0 && <div style={{ fontSize: 11.5, color: "#f5b942", marginTop: 6 }}>Ancora da controllare: {mancano.map((v) => v.testo.split(":")[0].split(" (")[0]).join(" · ")}</div>}
            </details>
          );
        })()}
        <DaGirare piano={p} />
        {/* senza foto scelte nel piano il riquadro qui sopra non c'è: le impostazioni della camera le mostro lo stesso */}
        {TIPI_ISPEZIONE.includes(p.tipo_ispezione) && !(p.checklist_stato?.manovre || []).length && <ImpostazioniIspezione tipo={p.tipo_ispezione} />}

        <ConsigliVolo tipo={p.tipo_ispezione} drone={drone} />

        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 12 }}>
          <button onClick={() => onApriPiano(p.id)} style={btn(true)}>Apri il piano</button>
          <button onClick={() => onDocumenti(p.id)} style={btn(false)}>🚔 Documenti controllo</button>
          <PulsantiNavigatore piano={p} />
          <button onClick={() => onRegistra(datiRegistro())} style={btn(false)}>📒 Registra il volo</button>
        </div>
        <div style={{ marginTop: 8 }}><PulsantiCalendario dati={calendarioDaPiano(p, drone)} compatto /></div>
      </div>
      {elencoAltri}
    </section>
  );
}

// «Sono già sul posto»: niente piano preparato prima, apro Pianifica sulla posizione GPS con data e ora di adesso
function VoloAdesso() {
  const [cerco, setCerco] = useState(false);
  const vai = (luogo) => vaiA({ pagina: "pianificazione", luogo: { nome: luogo ? "La mia posizione" : "", adesso: true, ...(luogo || {}) } });
  const premi = () => {
    if (!navigator.geolocation) { vai(null); return; }
    setCerco(true);
    navigator.geolocation.getCurrentPosition(
      (pos) => { setCerco(false); vai({ lat: pos.coords.latitude, lon: pos.coords.longitude }); },
      () => { setCerco(false); vai(null); },
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 60000 }
    );
  };
  return (
    <button type="button" onClick={premi} disabled={cerco} className="home-azione">
      <span className="home-azione-emoji" style={{ background: "#ff8c4226" }}>📍</span>
      <span>
        <span className="home-azione-titolo">{cerco ? "Cerco la posizione…" : <><span className="lungo">Sei sul posto? Vola adesso</span><span className="corto">Sono sul posto</span></>}</span>
        <span className="home-azione-testo">Meteo, zona, regole e camera, qui e ora</span>
      </span>
    </button>
  );
}


// «Oggi si vola?»: meteo di dove sei adesso. Chiede la posizione solo se il permesso c'è già o se lo tocchi
const CHIAVE_METEO_QUI = "eyedrones_meteo_qui";
function SiVolaQui() {
  const [m, setM] = useState(() => { try { const c = JSON.parse(sessionStorage.getItem(CHIAVE_METEO_QUI) || "null"); return c && Date.now() - c.quando < 30 * 60000 ? c : null; } catch { return null; } });
  const [stato, setStato] = useState(m ? "ok" : "fermo");
  const cerca = () => {
    if (!navigator.geolocation) { setStato("errore"); return; }
    setStato("cerco");
    navigator.geolocation.getCurrentPosition(async (pos) => {
      try {
        const { latitude: la, longitude: lo } = pos.coords;
        const [r, g] = await Promise.all([
          fetch(`https://api.open-meteo.com/v1/forecast?latitude=${la}&longitude=${lo}&current=temperature_2m,wind_speed_10m,wind_gusts_10m,precipitation,weather_code&timezone=auto`).then((x) => x.json()),
          fetch(`https://nominatim.openstreetmap.org/reverse?format=json&zoom=10&lat=${la}&lon=${lo}&accept-language=it`).then((x) => x.json()).catch(() => null),
        ]);
        const c = r.current || {};
        const a = g && g.address;
        const nuovo = { quando: Date.now(), luogo: a ? a.city || a.town || a.village || a.municipality || "" : "", t: c.temperature_2m, v: c.wind_speed_10m, raff: c.wind_gusts_10m, pioggia: c.precipitation, codice: c.weather_code };
        setM(nuovo); setStato("ok");
        try { sessionStorage.setItem(CHIAVE_METEO_QUI, JSON.stringify(nuovo)); } catch { /* niente */ }
      } catch { setStato("errore"); }
    }, () => setStato("errore"), { timeout: 12000, maximumAge: 10 * 60000 });
  };
  useEffect(() => {
    if (m) return;
    try { navigator.permissions?.query({ name: "geolocation" }).then((p) => { if (p.state === "granted") cerca(); }, () => {}); } catch { /* non supportato */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const vetro = { display: "inline-flex", alignItems: "center", gap: 10, background: "rgba(14,17,22,.62)", backdropFilter: "blur(8px)", WebkitBackdropFilter: "blur(8px)", border: "1px solid rgba(255,255,255,.14)", borderRadius: 12, padding: "10px 14px", color: "#e7eaee", textAlign: "left" };
  if (stato !== "ok" || !m) {
    return (
      <button type="button" onClick={cerca} disabled={stato === "cerco"} style={vetro}>
        <span style={{ fontSize: 22 }}>🌤️</span>
        <span><span style={{ display: "block", fontSize: 14, fontWeight: 700 }}>{stato === "cerco" ? "Guardo il meteo…" : "Oggi si vola?"}</span>
          <span style={{ display: "block", fontSize: 12, color: "#c3cad4" }}>{stato === "errore" ? "Posizione non disponibile: riprova" : "Tocca per vedere vento e pioggia dove sei"}</span></span>
      </button>
    );
  }
  const piove = (m.pioggia || 0) > 0.2 || [61, 63, 65, 66, 67, 80, 81, 82, 95, 96, 99].includes(m.codice);
  const ventoso = (m.raff || 0) > 38 || (m.v || 0) > 28;
  const quasi = (m.raff || 0) > 28 || (m.v || 0) > 20;
  const [emoji, titolo, colore] = piove ? ["🌧️", "Piove: meglio aspettare", "#ff8c42"] : ventoso ? ["💨", "Troppo vento per volare tranquilli", "#ff8c42"] : quasi ? ["🌬️", "Si vola, ma c'è vento", "#f5b942"] : ["✅", "Oggi si vola bene", "#4ade80"];
  return (
    <button type="button" onClick={() => vaiA({ pagina: "pianificazione", luogo: { nome: "La mia posizione", adesso: true } })} style={vetro} title="Apri il meteo completo in Pianifica">
      <span style={{ fontSize: 24 }}>{emoji}</span>
      <span>
        <span style={{ display: "block", fontSize: 14.5, fontWeight: 700, color: colore }}>{titolo}</span>
        <span style={{ display: "block", fontSize: 12, color: "#c3cad4" }}>{[m.luogo, m.t != null ? `${Math.round(m.t)}°` : null, m.v != null ? `vento ${Math.round(m.v)} km/h` : null, m.raff != null ? `raffiche ${Math.round(m.raff)}` : null].filter(Boolean).join(" · ")}</span>
      </span>
    </button>
  );
}

// le ultime foto e video caricati: in Home fanno da vetrina
function StrisciaLavori({ media, onApri }) {
  if (!media || media.length < 2) return null;
  return (
    <section style={{ marginBottom: 24 }}>
      <TitoloSezione emoji="🎞️" titolo="I tuoi ultimi lavori" azione={<button type="button" onClick={onApri} style={{ background: "none", border: "none", color: "#3d8bfd", fontSize: 12.5, padding: 0 }}>Galleria →</button>} />
      <div className="home-striscia">
        {media.slice(0, 10).map((x) => (
          <button key={x.id} type="button" onClick={onApri} aria-label={x.nome || "Apri la galleria"} style={{ flex: "none", width: 150, height: 96, padding: 0, border: "1px solid #2b313d", borderRadius: 10, overflow: "hidden", background: "#0e1116", position: "relative" }}>
            {x.tipo === "video"
              ? <video src={`${x.url}#t=0.5`} muted playsInline preload="metadata" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
              : <img src={x.url} alt="" loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />}
            {x.tipo === "video" && <span style={{ position: "absolute", left: 6, bottom: 6, background: "rgba(0,0,0,.6)", color: "#fff", fontSize: 11, borderRadius: 6, padding: "2px 6px" }}>▶ video</span>}
          </button>
        ))}
      </div>
    </section>
  );
}

