// --- Controllo zona di volo (file zone UAS di D-Flight) -------------------------------------------

// "P5D" → "5 giorni", "PT48H" → "48 ore" (durate ISO usate da D-Flight per il preavviso)
const durataLeggibile = (d) => {
  const m = String(d || "").match(/^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?)?$/i);
  if (!m || !(m[1] || m[2] || m[3])) return d;
  return [m[1] && `${m[1]} ${m[1] === "1" ? "giorno" : "giorni"}`, m[2] && `${m[2]} ${m[2] === "1" ? "ora" : "ore"}`, m[3] && `${m[3]} min`].filter(Boolean).join(" e ");
};
const SERVIZI_ENTE = { AUTHORIZATION: "autorizzazioni", INFORMATION: "informazioni" };

// cerca un indirizzo in Italia (via, numero, comune) con OpenStreetMap; se col numero civico non lo trova, riprova
// senza numero (punto a metà della via). Restituisce { lat, lon, etichetta } oppure null
async function cercaIndirizzoItalia(testo) {
  const pulito = String(testo || "").trim().replace(/([a-zà-ù])(\d)/gi, "$1 $2").replace(/(\d)([a-zà-ù]{3,})/gi, "$1 $2").replace(/\s{2,}/g, " ");
  if (!pulito) return null;
  const senzaNumero = pulito.replace(/\b(n\.?|nr\.?|civico)\s*/gi, "").replace(/\b\d+\s*[a-z]?(\/\s*\d+)?\b/gi, "").replace(/\s+,/g, ",").replace(/\s{2,}/g, " ").trim();
  // «via Roma 148 cafasse» senza virgola: provo anche «via Roma 148, cafasse» (l'ultima parola come comune)
  const parole = pulito.split(" ");
  const conVirgola = !pulito.includes(",") && parole.length >= 3 ? `${parole.slice(0, -1).join(" ")}, ${parole.at(-1)}` : null;
  for (const q of [...new Set([pulito, conVirgola, senzaNumero].filter(Boolean))]) {
    try {
      const r = await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&addressdetails=1&countrycodes=it&accept-language=it&q=${encodeURIComponent(q)}`);
      const [primo] = await r.json();
      if (primo) {
        // quanto è preciso il punto: il civico, solo la via (metà strada) o solo il paese (il centro)
        const a = primo.address || {};
        const precisione = a.house_number ? "civico" : a.road || a.pedestrian || a.footway || a.square ? "via" : "zona";
        const trovato = { lat: Number(primo.lat), lon: Number(primo.lon), etichetta: primo.display_name, precisione };
        // il civico non è sulla mappa: provo coi numeri vicini della stessa via
        const numero = Number([...pulito.matchAll(/\b(\d{1,4})\s*[a-z]?\b/gi)].at(-1)?.[1]); // l'ultimo numero (via 4 Novembre 12 → 12)
        if (precisione === "via" && numero > 0 && a.road) return (await civicoVicino(trovato, a.road, numero)) || trovato;
        return trovato;
      }
    } catch (e) { /* provo la variante successiva */ }
  }
  return null;
}

// il civico cercato non c'è su OpenStreetMap: prendo i numeri segnati della stessa via (stesso lato, pari o dispari)
// e metto il punto a metà tra quello prima e quello dopo, oppure su quello più vicino
async function civicoVicino(via, strada, numero) {
  const nome = strada.replace(/["\\]/g, "");
  const q = `[out:json][timeout:15];nwr(around:2500,${via.lat},${via.lon})["addr:street"="${nome}"]["addr:housenumber"];out center 400;`;
  const server = ["https://overpass-api.de/api/interpreter", "https://overpass.kumi.systems/api/interpreter"];
  let elementi = null;
  try {
    elementi = await Promise.any(server.map(async (u) => {
      const r = await fetch(u, { method: "POST", body: "data=" + encodeURIComponent(q), headers: { "Content-Type": "application/x-www-form-urlencoded" } });
      if (!r.ok) throw new Error("overpass");
      return (await r.json()).elements || [];
    }));
  } catch { return null; }
  const civici = elementi.map((e) => ({ n: parseInt(e.tags?.["addr:housenumber"], 10), lat: e.lat ?? e.center?.lat, lon: e.lon ?? e.center?.lon }))
    .filter((c) => c.n > 0 && c.lat != null && c.lon != null);
  if (civici.length === 0) return null;
  const esatto = civici.find((c) => c.n === numero);
  if (esatto) return { ...via, lat: esatto.lat, lon: esatto.lon, precisione: "civico" };
  const stessoLato = civici.filter((c) => c.n % 2 === numero % 2);
  const elenco = stessoLato.length > 0 ? stessoLato : civici;
  const prima = elenco.filter((c) => c.n < numero).sort((x, y) => y.n - x.n)[0];
  const dopo = elenco.filter((c) => c.n > numero).sort((x, y) => x.n - y.n)[0];
  if (prima && dopo && dopo.n - prima.n <= 40) {
    const f = (numero - prima.n) / (dopo.n - prima.n);
    return { ...via, lat: prima.lat + (dopo.lat - prima.lat) * f, lon: prima.lon + (dopo.lon - prima.lon) * f, precisione: "vicino", nota: `Il ${numero} non è sulla mappa: ho messo il punto tra il ${prima.n} e il ${dopo.n}.` };
  }
  const vicino = [prima, dopo].filter(Boolean).sort((x, y) => Math.abs(x.n - numero) - Math.abs(y.n - numero))[0];
  if (!vicino || Math.abs(vicino.n - numero) > 30) return null;
  return { ...via, lat: vicino.lat, lon: vicino.lon, precisione: "vicino", nota: `Il ${numero} non è sulla mappa: ho usato il ${vicino.n}, il più vicino.` };
}

// copia del file zone nello spazio privato dell'account: se il telefono lo cancella, l'app lo riprende da sola
const NOME_COPIA_ZONE = "zone-uas.json";
async function salvaCopiaZone(dati) {
  try {
    const uid = await idUtenteCorrente();
    if (!uid) return;
    const blob = new Blob([JSON.stringify(dati)], { type: "application/json" });
    await supabase.storage.from(BUCKET_RISERVATO).upload(`${uid}/${NOME_COPIA_ZONE}`, blob, { upsert: true, contentType: "application/json" });
  } catch { /* la copia è solo una sicurezza in più */ }
}
async function riprendiCopiaZone() {
  try {
    const uid = await idUtenteCorrente();
    if (!uid) return null;
    const { data, error } = await supabase.storage.from(BUCKET_RISERVATO).download(`${uid}/${NOME_COPIA_ZONE}`);
    if (error || !data) return null;
    const dati = JSON.parse(await data.text());
    if (!dati || !Array.isArray(dati.zone) || dati.zone.length === 0) return null;
    if (!dati.caricato) dati.caricato = new Date().toISOString();
    const sistemati = sistemaArchivio(dati);
    await salvaZone(sistemati);
    return sistemati;
  } catch { return null; }
}

// legge il file zone scelto dal pilota, lo salva sul telefono e nell'account; se non va lancia un errore da mostrare
async function caricaFileZone(file) {
  let zone;
  try { zone = leggiFileZone(JSON.parse(await testoDaFileZone(file))); } catch (err) { throw new Error(err instanceof SyntaxError ? "Il file non è un JSON valido: scaricalo di nuovo da D-Flight." : (err.message || "Non sono riuscito a leggere il file.")); }
  if (zone.length === 0) throw new Error("Non ho trovato zone in questo file: è quello scaricato da D-Flight («Download UAS Zone Geo»)?");
  const dati = { zone, nomeFile: file.name, caricato: new Date().toISOString() };
  await salvaZone(dati);
  salvaCopiaZone(dati).then(() => { try { localStorage.setItem("eyedrones_zone_copia", dati.caricato); } catch { /* niente */ } });
  return dati;
}

// in Pianifica, prima di scegliere il posto: il file zone si vede e si carica subito (prima compariva solo dopo)
function FileZoneVeloce() {
  const [archivio, setArchivio] = useState(undefined);
  const [leggo, setLeggo] = useState(false);
  const [errore, setErrore] = useState(null);
  useEffect(() => { leggiZoneSalvate().then(async (d) => setArchivio(d && Array.isArray(d.zone) ? d : (await riprendiCopiaZone()) || null)); }, []);
  const carica = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setLeggo(true); setErrore(null);
    try { setArchivio(await caricaFileZone(file)); } catch (err) { setErrore(err.message); }
    setLeggo(false);
  };
  if (archivio === undefined) return null;
  const giorni = archivio ? Math.floor((Date.now() - new Date(archivio.caricato).getTime()) / 86400000) : 0;
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", background: archivio ? "#1b2028" : "#3a2a12", border: `1px solid ${archivio ? "#2b313d" : "#f5b94266"}`, borderRadius: 10, padding: "10px 14px", marginBottom: 16, maxWidth: 620, fontSize: 12.5, color: archivio ? "#c3cad4" : "#ffd9a0" }}>
      <span style={{ flex: "1 1 220px" }}>
        🛡️ <strong>File zone di D-Flight</strong>: {archivio ? <>caricato il {formatData(String(archivio.caricato || "").slice(0, 10))} ({archivio.zone.length} zone){giorni > 28 ? <span style={{ color: "#f5b942" }}> · ⚠ aggiornalo</span> : " ✓"}</> : "non ancora caricato. Serve per sapere se nel posto puoi volare."}
        {errore && <span style={{ display: "block", color: "#ff9c9c", marginTop: 4 }}>{errore}</span>}
      </span>
      <label style={{ display: "inline-block", background: "#1f2a3a", border: "1px solid #3d8bfd88", color: "#7fb0ff", borderRadius: 6, padding: "7px 14px", fontSize: 12.5, fontWeight: 600, cursor: "pointer" }}>
        {leggo ? "Sto leggendo il file…" : archivio ? "📂 Aggiorna il file" : "📂 Carica il file zone"}
        <input type="file" onChange={carica} disabled={leggo} style={{ display: "none" }} />
      </label>
    </div>
  );
}

function ControlloZona({ testoLuogo, coordinate, puntoIndicativo, puntoCercato, onPuntoCercato, dataPrevista, oraPrevista, piano, onEsito, onStato }) {
  const [archivio, setArchivio] = useState(undefined); // undefined = sto leggendo, null = nessun file
  const [leggendoFile, setLeggendoFile] = useState(false);
  const [errore, setErrore] = useState(null);
  const [cercando, setCercando] = useState(false);

  const [ripreso, setRipreso] = useState(false);
  useEffect(() => {
    let annullato = false;
    leggiZoneSalvate().then(async (d) => {
      if (d && Array.isArray(d.zone)) {
        if (annullato) return;
        setArchivio(d); chiediSpazioPermanente();
        try {
          localStorage.setItem("eyedrones_zone_caricate", d.caricato || "");
          // file caricato prima che esistesse la copia nell'account: la faccio adesso, una volta
          if (localStorage.getItem("eyedrones_zone_copia") !== (d.caricato || "")) salvaCopiaZone(d).then(() => { try { localStorage.setItem("eyedrones_zone_copia", d.caricato || ""); } catch { /* niente */ } });
        } catch { /* niente */ }
        return;
      }
      // sul telefono non c'è: provo a riprendere la copia dal tuo account
      const copia = await riprendiCopiaZone();
      if (annullato) return;
      setArchivio(copia || null);
      if (copia) setRipreso(true);
    });
    return () => { annullato = true; };
  }, []);
  const caricatoPrima = zoneCaricatePrima();

  const caricaFile = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setLeggendoFile(true);
    setErrore(null);
    try {
      setArchivio(await caricaFileZone(file));
    } catch (err) {
      setErrore(err.message);
    }
    setLeggendoFile(false);
  };

  const cercaIndirizzo = async () => {
    if (!testoLuogo) return;
    setCercando(true);
    setErrore(null);
    const trovato = await cercaIndirizzoItalia(testoLuogo);
    if (trovato) onPuntoCercato(trovato);
    else setErrore("Indirizzo non trovato: prova a scrivere via e comune (es. Via Roma 4, Torino), oppure le coordinate.");
    setCercando(false);
  };

  // appena smetti di scrivere il luogo lo cerco da solo (senza toccare «Trova l'indirizzo»)
  useEffect(() => {
    const t = (testoLuogo || "").trim();
    if (coordinate || puntoCercato || t.length < 5) return undefined;
    let annullato = false;
    const timer = setTimeout(async () => {
      setCercando(true); setErrore(null);
      const trovato = await cercaIndirizzoItalia(t);
      setCercando(false);
      if (annullato) return;
      if (trovato) onPuntoCercato(trovato);
      else setErrore("Indirizzo non trovato: prova a scrivere via e comune (es. Via Roma 4, Torino), oppure le coordinate.");
    }, 1300);
    return () => { annullato = true; clearTimeout(timer); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [testoLuogo, coordinate, puntoCercato]);

  const punto = coordinate
    ? { lat: coordinate.lat, lon: coordinate.lon, fonte: "coordinate" }
    : puntoCercato
      ? { ...puntoCercato, fonte: "indirizzo" }
      : puntoIndicativo && puntoIndicativo.lat != null && !cercando // mentre cerco la via non uso il centro del paese
        ? { lat: puntoIndicativo.lat, lon: puntoIndicativo.lon, fonte: "indicativo" }
        : null;
  // il punto trovato non è sul civico esatto: lo dico e chiedo di controllare il puntino
  const approssimato = punto && (punto.fonte === "indicativo" || (punto.fonte === "indirizzo" && punto.precisione && !["civico", "mano"].includes(punto.precisione)));
  const spostaPunto = React.useCallback((lat, lon) => onPuntoCercato({ lat, lon, etichetta: null, precisione: "mano" }), [onPuntoCercato]);
  const zone = archivio && archivio.zone;
  const quando = dataPrevista ? new Date(`${dataPrevista}T${oraPrevista || "12:00"}`) : null;
  const latP = punto && punto.lat, lonP = punto && punto.lon;
  const esito = React.useMemo(
    () => {
      if (!zone || latP == null) return null;
      const e = controllaPunto(zone, { lat: latP, lon: lonP }, { raggio: 500, quando });
      // le date dei NOTAM sono vere: se il giorno del volo il NOTAM non c'è, non lo conto (lo dico a parte)
      const fuori = (z) => z.tipoUAS === "notam" && (z.fuoriPeriodo || zonaFinita(z));
      return { dentro: e.dentro.filter((z) => !fuori(z)), vicine: e.vicine.filter((z) => !fuori(z)), notamFuori: e.dentro.filter(fuori) };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [zone, latP, lonP, dataPrevista, oraPrevista]
  );

  // al riquadro delle regole dico se la zona è stata davvero controllata (se no, niente «120 m» che sembra un via libera)
  const pro = sbloccatoPro(piano);
  const motivoStato = !pro ? "pro" : archivio === undefined ? "carico" : !archivio ? "file" : !punto ? (cercando ? "cerco" : errore ? "indirizzo" : "luogo") : punto.fonte === "indicativo" ? "centro" : null;
  useEffect(() => {
    if (onStato) onStato({ controllata: !motivoStato && !!esito, motivo: motivoStato, approssimata: !!approssimato });
  }, [motivoStato, !!esito, !!approssimato]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => () => { if (onStato) onStato(null); }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // riassunto salvato nel piano di volo e stampato nel PDF di controllo
  const avevaEsito = useRef(false);
  useEffect(() => {
    // il punto è cambiato e ora non c'è più un controllo valido: tolgo il vecchio risultato
    if (!esito) { if (avevaEsito.current && onEsito) onEsito(null); avevaEsito.current = false; return; }
    avevaEsito.current = true;
    if (!onEsito) return;
    onEsito({
      verificata: new Date().toISOString(),
      fileDel: archivio.caricato,
      punto: `${latP.toFixed(5)}, ${lonP.toFixed(5)}`,
      zone: esito.dentro.map((z) => {
        // l'ente a cui chiedere il permesso (per il riquadro delle regole e il PDF)
        const a = (z.autorita || []).find((x) => valoreReale(x.nome) || valoreReale(x.email)) || {};
        return { nome: z.nome, restrizione: z.restrizione, limiti: formattaLimiti(z.limiti), da: partenzaZona(z), ente: valoreReale(a.nome) || null, email: valoreReale(a.email) || null, preavviso: valoreReale(a.preavviso) || null };
      }),
      altezzaLibera: altezzaLibera(esito.dentro),
      vicino: limiteVicino(esito.vicine, 150),
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [esito]);

  const giorniFile = archivio ? Math.floor((Date.now() - new Date(archivio.caricato).getTime()) / 86400000) : 0;
  const box = { marginTop: 10, background: "#161a1f", border: "1px solid #262b33", borderRadius: 6, padding: 12 };
  const linkD = { color: "#3d8bfd", fontSize: 12 };

  const schedaZona = (z, vicina) => {
    const base = descriviRestrizione(z.restrizione);
    const parte = z.restrizione === "NO_RESTRICTION" ? 0 : partenzaZona(z);
    const scritta = z.restrizione === "NO_RESTRICTION" ? null : altezzaDaTesto(z);
    const sopra = z.restrizione === "PROHIBITED" ? "vietato" : z.restrizione === "REQ_AUTHORISATION" ? "serve autorizzazione" : "con le condizioni della zona";
    // la zona comincia sopra il suolo: fino a quell'altezza si vola con le regole normali
    const d = parte > 0
      ? { ...base, colore: "#f5b942", etichetta: `Libero fino a ${parte} m · sopra ${sopra}`, consiglio: `Fino a ${parte} m dal suolo puoi volare senza autorizzazione, con le regole della tua categoria. Per salire oltre i ${parte} m ${z.restrizione === "PROHIBITED" ? "non si può" : z.restrizione === "REQ_AUTHORISATION" ? "chiedi l'autorizzazione all'ente indicato (spesso tramite D-Flight)" : "rispetta le condizioni scritte qui sotto o chiedi all'ente indicato"}.` }
      : scritta != null && z.restrizione !== "PROHIBITED"
        ? { ...base, colore: "#f5b942", etichetta: `Massimo ${scritta} m · ${base.etichetta.toLowerCase()}`, consiglio: `Secondo il messaggio della zona qui si vola al massimo a ${scritta} m dal suolo. ${base.consiglio}` }
        : base;
    const limiti = formattaLimiti(z.limiti);
    const autorita = (z.autorita || []).map((a) => ({ ...a, nome: valoreReale(a.nome), servizio: valoreReale(a.servizio), email: valoreReale(a.email), telefono: valoreReale(a.telefono), sito: valoreReale(a.sito), preavviso: valoreReale(a.preavviso) }))
      .filter((a) => a.nome || a.email || a.telefono || a.sito);
    const motivo = motivoZona(z);
    const notam = z.tipoUAS === "notam";
    const zonaR = /\bLI[\s-]?R\s?\d/i.test(z.nome || "");
    const consiglio = !notam ? d.consiglio : "Nei giorni del NOTAM qui non si vola, né in Open né in Specific: lo spazio è riservato a un'altra attività e non puoi chiedere di entrarci. Fuori da quelle date la zona non c'è. Un NOTAM tuo invece, in Specific (STS o autorizzazione ENAC), si chiede con il Modello ATM-09A: ENAC lo fa uscire almeno 7 giorni prima del volo.";
    return (
      <div key={(z.id || z.nome) + (vicina ? "-v" : "")} style={{ borderLeft: `3px solid ${d.colore}`, background: d.colore + "12", borderRadius: 4, padding: "8px 10px", marginTop: 6 }}>
        <div style={{ fontSize: 12.5, fontWeight: 700, color: d.colore }}>{d.etichetta}{vicina ? <span style={{ color: "#8b95a3", fontWeight: 400 }}> · a {z.distanza} m</span> : null}{z.temporanea ? <span style={{ color: "#f5b942", fontWeight: 400 }}> · temporanea</span> : null}</div>
        <div style={{ fontSize: 12.5, color: "#e7eaee", marginTop: 2 }}>{z.nome}</div>
        {limiti && <div style={{ fontSize: 12, color: "#c3cad4", marginTop: 2 }}>↕️ Zona {limiti}</div>}
        {motivo && <div style={{ fontSize: 11.5, color: "#8b95a3", marginTop: 2 }}>Motivo: {motivo}</div>}
        {!vicina && notam && valoreReale(z.messaggio) && <NotamInItaliano testo={z.messaggio} />}
        {!vicina && !notam && valoreReale(z.messaggio) && <div style={{ fontSize: 11.5, color: "#c3cad4", marginTop: 4, whiteSpace: "pre-wrap" }}>{messaggioBreve(z.messaggio)}</div>}
        {!vicina && zonaR && <div style={{ fontSize: 11.5, color: "#ffd9a0", marginTop: 3 }}>⏰ Zona LI-R: vale <strong>solo quando è attiva</strong>. Gli orari sono nell'AIP Italia (ENR 5.1.2): su D-Flight tocca la zona → «Regole dell'aria». Può essere attivata anche con un NOTAM.</div>}
        {!vicina && valoreReale(z.condizioni) && <div style={{ fontSize: 11.5, color: "#c3cad4", marginTop: 2 }}>Condizioni: {z.condizioni}</div>}
        {z.fuoriPeriodo && <div style={{ fontSize: 11.5, color: "#ffb877", marginTop: 3 }}>⚠ Secondo il file questa zona non vale il giorno del volo, ma le date del file potrebbero essere solo vecchie: per sicurezza la considero attiva. Aggiorna il file e controlla su D-Flight.</div>}
        {!vicina && z.validita && <div style={{ fontSize: 11.5, color: "#f5b942", marginTop: 2 }}>Attiva: {z.validita.map((v) => `${v.da ? formatData(String(v.da).slice(0, 10)) : "…"} → ${v.a ? formatData(String(v.a).slice(0, 10)) : "…"}`).join(" · ")}</div>}
        {!vicina && <div style={{ fontSize: 11.5, color: "#e7eaee", marginTop: 4 }}>👉 {consiglio}</div>}
        {!vicina && notam && <AvvisaFineNotam zona={z} posto={testoLuogo || `${latP.toFixed(4)}, ${lonP.toFixed(4)}`} />}
        {!vicina && !notam && (z.restrizione === "REQ_AUTHORISATION" || z.restrizione === "PROHIBITED") && (
          <span style={{ display: "inline-flex", gap: 6, flexWrap: "wrap", marginTop: 6 }}>
            <button type="button" onClick={() => vaiA({ pagina: "impara", scheda: "zona-rossa", sopra: true })} style={{ background: "none", border: "1px solid #ff8c4266", color: "#ffb877", borderRadius: 5, padding: "4px 9px", fontSize: 11.5 }}>🔴 Come si fa a volare qui?</button>
            <button type="button" onClick={() => { try { sessionStorage.setItem("eyedrones_assistente_permessi", "si"); } catch { /* niente */ } vaiA({ pagina: "permessi" }); }} style={{ background: "#1d2633", border: "1px solid #3d8bfd66", color: "#9fc5ff", borderRadius: 5, padding: "4px 9px", fontSize: 11.5, fontWeight: 600 }}>🧭 Preparami la richiesta</button>
          </span>
        )}
        {!vicina && autorita.map((a, i) => (
          <div key={i} style={{ fontSize: 11.5, color: "#c3cad4", marginTop: 3 }}>
            🏛️ {a.nome || "Ente"}{a.servizio ? ` (${SERVIZI_ENTE[a.servizio.toUpperCase()] || a.servizio})` : ""}
            {a.preavviso ? ` · chiedi con almeno ${durataLeggibile(a.preavviso)} di anticipo` : ""}
            {a.email && <> · <a href={`mailto:${a.email}`} style={linkD}>{a.email}</a></>}
            {a.telefono && <> · <a href={`tel:${a.telefono}`} style={linkD}>{a.telefono}</a></>}
            {a.sito && <> · <a href={/^https?:/i.test(a.sito) ? a.sito : `https://${a.sito}`} target="_blank" rel="noreferrer" style={linkD}>sito ↗</a></>}
          </div>
        ))}
      </div>
    );
  };

  return (
    <div style={{ ...box, border: "1px solid #3d8bfd55" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        <span style={{ fontSize: 13, fontWeight: 700 }}>🛡️ Zona di volo<EtichettaPro /></span>
        {archivio && (
          <label style={{ fontSize: 11, color: giorniFile > 28 ? "#f5b942" : "#8b95a3", cursor: "pointer" }}>
            {ripreso ? "☁️ Ripreso dal tuo account · " : ""}File zone del {formatData(String(archivio.caricato || "").slice(0, 10))}{giorniFile > 28 ? " ⚠ aggiornalo" : ""} · <span style={{ color: "#3d8bfd" }}>{leggendoFile ? "lettura…" : "aggiorna"}</span>
            <input type="file" onChange={caricaFile} style={{ display: "none" }} />
          </label>
        )}
      </div>
      {/* il volo è tra pochi giorni e il file è di qualche giorno fa: i NOTAM nuovi non ci sono ancora */}
      {archivio && dataPrevista && (() => {
        const traGiorni = Math.round((new Date(`${dataPrevista}T12:00`).getTime() - Date.now()) / 86400000);
        return traGiorni >= 0 && traGiorni <= 3 && giorniFile >= 2 ? (
          <label style={{ display: "block", marginTop: 6, fontSize: 11.5, color: "#ffd9a0", background: "#3a2a12", border: "1px solid #f5b94255", borderRadius: 6, padding: "6px 9px", cursor: "pointer" }}>
            ⚠ Il volo è {traGiorni === 0 ? "oggi" : traGiorni === 1 ? "domani" : `tra ${traGiorni} giorni`} e il file zone è di {giorniFile} giorni fa: i <strong>NOTAM</strong> nuovi non ci sono. Riscaricalo da D-Flight e <span style={{ color: "#3d8bfd" }}>caricalo qui</span>.
            <input type="file" onChange={caricaFile} style={{ display: "none" }} />
          </label>
        ) : null;
      })()}

      {!sbloccatoPro(piano) ? (
        <InvitoPro cosa="Il controllo automatico della zona" />
      ) : archivio === undefined ? (
        <p style={{ fontSize: 12, color: "#8b95a3", margin: "6px 0 0 0" }}>Carico le zone…</p>
      ) : !archivio ? (
        <div style={{ fontSize: 12.5, color: "#c3cad4", marginTop: 6 }}>
          {caricatoPrima && <div style={{ background: "#3a2a12", border: "1px solid #f5b94266", color: "#ffd9a0", borderRadius: 6, padding: "8px 10px", marginBottom: 8, fontWeight: 600 }}>⚠ Il file delle zone che avevi caricato il {formatData(String(caricatoPrima).slice(0, 10))} non c'è più su questo telefono (a volte il telefono libera spazio cancellando i dati dei siti, o hai cambiato browser). Finché non lo ricarichi, la zona non viene controllata.</div>}
          <div style={{ fontWeight: 700, color: "#e7eaee", fontSize: 13 }}>Per sapere se qui puoi volare serve il file delle zone di D-Flight</div>
          <div style={{ color: "#aab3bf", fontSize: 12, marginTop: 2 }}>È gratis e si fa <strong>una volta sola</strong>: poi l'app ti dice da sola se la zona è vietata, se serve l'autorizzazione, fino a che altezza puoi salire e chi contattare.</div>
          <ol style={{ margin: "8px 0", paddingLeft: 20, color: "#c3cad4", fontSize: 12.5, lineHeight: 1.5 }}>
            <li>Tocca <a href="https://www.d-flight.it/web-app/" target="_blank" rel="noreferrer" style={{ ...linkD, fontSize: 12.5, fontWeight: 700 }}>🗺️ Apri D-Flight ↗</a> ed entra con le tue credenziali.</li>
            <li>In alto a sinistra tocca il pulsante col logo <strong>«d»</strong>.</li>
            <li>Sotto <strong>«Dettagli account»</strong> tocca il <strong>dischetto 💾</strong> (<em>Download UAS Zone Geo</em>). Il file si salva nella cartella <strong>Download</strong> del telefono.</li>
            <li>Torna qui e tocca <strong>«📂 Carica il file zone di D-Flight»</strong> qui sotto. Si apre l'elenco dei file: tocca <strong>Recenti</strong> (o ☰ → <strong>Download</strong>) e scegli <strong>dflight_geozones_….json.gz</strong>, quello con la data più nuova.</li>
            <li>Scrivi la via del volo: l'app ti dice subito la zona e l'altezza massima.</li>
          </ol>
          <div style={{ color: "#8b95a3", fontSize: 11.5, marginBottom: 8 }}>Il file resta salvato anche nel tuo account, così non lo perdi se cambi telefono. Aggiornalo una volta al mese.</div>
          <label style={{ display: "inline-block", background: "#1f2a3a", border: "1px solid #3d8bfd88", color: "#7fb0ff", borderRadius: 6, padding: "7px 14px", fontSize: 12.5, fontWeight: 600, cursor: "pointer" }}>
            {leggendoFile ? "Sto leggendo il file…" : "📂 Carica il file zone di D-Flight"}
            <input type="file" onChange={caricaFile} disabled={leggendoFile} style={{ display: "none" }} />
          </label>
        </div>
      ) : (
        <div style={{ marginTop: 6 }}>
          <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", fontSize: 11.5, color: "#8b95a3" }}>
            {punto ? (
              <span>
                📍 {punto.fonte === "coordinate" ? "Coordinate" : punto.precisione === "mano" ? "Punto sulla mappa" : punto.fonte === "indirizzo" ? "Indirizzo trovato" : "Centro della località (indicativo)"}: {punto.lat.toFixed(5)}, {punto.lon.toFixed(5)}
                {" · "}<a href={`https://www.google.com/maps?q=${punto.lat},${punto.lon}`} target="_blank" rel="noreferrer" style={{ color: "#3d8bfd" }}>controlla sulla mappa ↗</a>
              </span>
            ) : (
              <span>{cercando ? "Cerco il luogo…" : "Scrivi via e comune (o le coordinate): lo cerco da solo appena smetti di scrivere."}</span>
            )}
            {!coordinate && testoLuogo && (
              <button type="button" onClick={cercaIndirizzo} disabled={cercando} style={{ background: "#262b33", border: "1px solid #333a45", color: "#c3cad4", borderRadius: 5, padding: "4px 10px", fontSize: 11.5 }}>
                {cercando ? "Cerco…" : "🔎 Trova l'indirizzo"}
              </button>
            )}
          </div>
          {punto && punto.etichetta && <p style={{ fontSize: 10.5, color: "#6b7480", margin: "2px 0 0 0" }}>{punto.etichetta}</p>}
          {approssimato && (
            <div style={{ background: "#3a2a12", border: "1px solid #f5b94266", color: "#ffd9a0", borderRadius: 6, padding: "8px 10px", marginTop: 6, fontSize: 12 }}>
              ⚠ <strong>Posizione approssimativa.</strong>{" "}
              {punto.fonte === "indicativo" ? "Il punto è il centro del paese, non il posto dove voli."
                : punto.nota ? punto.nota
                : punto.precisione === "via" ? "Ho trovato la via ma non il numero: il punto è a metà della via."
                : "Ho trovato solo il paese o la località, non la via."}
              {" "}Vicino al bordo di una zona può fare la differenza: <strong>trascina il puntino 📍 sulla mappa</strong> nel posto esatto (o tocca la mappa).
            </div>
          )}
          {punto && punto.precisione === "mano" && <p style={{ fontSize: 11, color: "#4ade80", margin: "4px 0 0 0" }}>✓ Punto messo da te sulla mappa</p>}
          {punto && (
            <Suspense fallback={null}>
              <MappaPunto punto={punto} zone={esito ? [...esito.dentro, ...esito.vicine] : null} onSposta={punto.fonte === "coordinate" ? null : spostaPunto} />
            </Suspense>
          )}
          {punto && punto.fonte !== "coordinate" && <p style={{ fontSize: 10.5, color: "#6b7480", margin: "3px 0 0 0" }}>Trascina il puntino o tocca la mappa per spostarlo: la zona si ricontrolla subito.</p>}

          {esito && esito.dentro.length === 0 && (
            <div style={{ borderLeft: "3px solid #4ade80", background: "#4ade8012", borderRadius: 4, padding: "8px 10px", marginTop: 8, fontSize: 12.5 }}>
              <div style={{ fontWeight: 700, color: "#4ade80" }}>✓ Nessuna zona geografica UAS su questo punto</div>
              <div style={{ color: "#c3cad4", marginTop: 2, fontSize: 12 }}>Valgono le regole generali della categoria Open: massimo 120 m dal suolo, drone sempre in vista, niente voli sopra assembramenti di persone.</div>
            </div>
          )}
          {esito && esito.dentro.length > 0 && (() => {
            const max = altezzaLibera(esito.dentro);
            const vietata = esito.dentro.some((z) => z.restrizione === "PROHIBITED" && partenzaZona(z) === 0);
            const [col, txt] = max >= 120 ? ["#4ade80", "Senza autorizzazione puoi volare fino a 120 m (con le condizioni della zona)"]
              : max > 0 ? ["#f5b942", `Senza autorizzazione qui puoi volare fino a ${max} m dal suolo`]
              : vietata ? ["#ff4d4d", "Qui il volo è vietato già da terra"] : ["#ff8c42", "Qui serve l'autorizzazione già da terra"];
            return <div style={{ marginTop: 8, padding: "8px 10px", borderRadius: 6, background: col + "1f", border: `1px solid ${col}66`, color: col, fontSize: 13, fontWeight: 700 }}>↕️ {txt}</div>;
          })()}
          {esito && (() => {
            // una zona più bassa a pochi metri: se l'area di volo ci entra, vale il limite più basso
            const v = limiteVicino(esito.vicine, approssimato ? 300 : 150);
            if (!v || v.altezza >= altezzaLibera(esito.dentro)) return null;
            return (
              <div style={{ marginTop: 8, padding: "8px 10px", borderRadius: 6, background: "#f5b9421f", border: "1px solid #f5b94266", color: "#ffd9a0", fontSize: 12.5 }}>
                <strong style={{ color: "#f5b942" }}>⚠ A {v.distanza} m c'è una zona {v.altezza > 0 ? `con limite di ${v.altezza} m` : "dove serve l'autorizzazione già da terra"}</strong> ({v.nome}).
                {" "}Se l'area di volo ci entra, anche di poco, {v.altezza > 0 ? `resta sotto i ${v.altezza} m` : "serve l'autorizzazione"}. {approssimato ? "La posizione è approssimativa: sposta il puntino nel punto esatto." : "Controlla l'area disegnata su D-Flight."}
              </div>
            );
          })()}
          {esito && esito.dentro.map((z) => schedaZona(z, false))}
          {esito && esito.notamFuori.map((z) => (
            <div key={"nf-" + (z.id || z.nome)} style={{ borderLeft: "3px solid #4ade80", background: "#4ade8012", borderRadius: 4, padding: "8px 10px", marginTop: 6, fontSize: 12, color: "#c3cad4" }}>
              ✓ <strong style={{ color: "#4ade80" }}>{z.nome}</strong>: qui c'è un NOTAM ({(z.validita || []).map((v) => `${v.da ? formatData(String(v.da).slice(0, 10)) : "…"} → ${v.a ? formatData(String(v.a).slice(0, 10)) : "…"}`).join(" · ")}), ma il giorno del volo non è attivo.
            </div>
          ))}
          {esito && esito.vicine.length > 0 && (
            <>
              <p style={{ fontSize: 11.5, color: "#8b95a3", margin: "10px 0 0 0" }}>Zone vicine (entro 500 m): attento a non sconfinare.</p>
              {esito.vicine.slice(0, 5).map((z) => schedaZona(z, true))}
            </>
          )}
          {esito && (
            <div style={{ fontSize: 11.5, color: "#c3cad4", marginTop: 10, paddingTop: 8, borderTop: "1px solid #262b33" }}>
              📣 <strong>NOTAM</strong>: avvisi temporanei (eventi, esercitazioni, elisoccorso) che non sempre sono nel file. Controllali su <a href="https://www.d-flight.it/web-app/" target="_blank" rel="noreferrer" style={linkD}>D-Flight ↗</a> il giorno prima e il giorno del volo.
            </div>
          )}
        </div>
      )}
      {errore && <p style={{ fontSize: 11.5, color: "#ff9c9c", margin: "6px 0 0 0" }}>{errore}</p>}
      <p style={{ fontSize: 10.5, color: "#6b7480", margin: "8px 0 0 0" }}>Aiuto alla pianificazione basato sul tuo file D-Flight: la verifica ufficiale resta su D-Flight prima di ogni volo.</p>
    </div>
  );
}

// --- Regole base del volo in categoria Open (Reg. UE 2019/947), in base alla classe del drone ------------------
// Promemoria semplificato: non sostituisce il manuale del drone né le regole ENAC.
const REGOLE_CLASSE = {
  C0: { sottocategoria: "A1", attestato: null, peso: "meno di 250 g", regole: ["Puoi sorvolare persone non coinvolte, ma evitalo quando puoi", "Mai sopra assembramenti di persone"] },
  C1: { sottocategoria: "A1", attestato: "A1/A3", peso: "meno di 900 g", regole: ["Non sorvolare di proposito persone non coinvolte (se capita, riduci il tempo sopra di loro)", "Mai sopra assembramenti di persone", "Remote ID attivo"] },
  C2: { sottocategoria: "A2", attestato: "A2", peso: "meno di 4 kg", regole: ["Almeno 30 m in orizzontale dalle persone non coinvolte (5 m con la modalità bassa velocità attiva)", "Mai sopra assembramenti di persone", "Remote ID attivo", "Senza attestato A2 voli solo in A3: lontano 150 m da centri abitati e aree industriali o ricreative"] },
  C3: { sottocategoria: "A3", attestato: "A1/A3", peso: "meno di 25 kg", regole: ["Nessuna persona non coinvolta nell'area di volo", "Almeno 150 m da aree residenziali, commerciali, industriali o ricreative", "Remote ID attivo"] },
  C4: { sottocategoria: "A3", attestato: "A1/A3", peso: "meno di 25 kg", regole: ["Nessuna persona non coinvolta nell'area di volo", "Almeno 150 m da aree residenziali, commerciali, industriali o ricreative"] },
};

// perché la zona non è stata controllata, detto semplice
const MOTIVI_ZONA_NON_CONTROLLATA = {
  file: "manca il file delle zone di D-Flight: caricalo qui sopra (si fa una volta sola)",
  indirizzo: "non ho trovato l'indirizzo: scrivi via, numero e comune, oppure tocca 📍 o metti le coordinate",
  cerco: "sto cercando l'indirizzo…",
  luogo: "scrivi la via del volo oppure le coordinate",
  centro: "ho solo il centro del paese: scrivi la via o sposta il puntino sulla mappa",
  pro: "il controllo automatico della zona è nel piano Pro: controlla la zona su D-Flight",
  carico: "sto caricando le zone…",
};

function RegoleVolo({ drone, altezzaZona, zonaVerificata = true, motivoZona, zonaApprossimata, zoneDelPunto, permessiRegistrati = 0, attestati, notte, fpv, tipo }) {
  const classe = (String(drone?.marcatura_classe || "").toUpperCase().match(/C\s*([0-6])/) || [])[1];
  const chiave = classe != null ? `C${classe}` : null;
  const info = chiave && REGOLE_CLASSE[chiave];
  const valido = (re) => (attestati || []).some((a) => re.test(a.tipo || "") && (!a.data_scadenza || new Date(a.data_scadenza) >= new Date()));
  const haA2 = valido(/\bA2\b/i);
  const haA1A3 = valido(/A1\s*\/?\s*A3/i) || haA2 || valido(/\bSTS\b/i); // per ottenere A2 o STS serve già l'A1/A3
  const haAssicurazione = valido(/assicura/i);
  const altezza = Math.min(120, altezzaZona ?? 120);

  const voce = (ok, testo) => <li style={{ marginTop: 3, color: ok === false ? "#ffb877" : "#c3cad4" }}>{ok === true ? "✓ " : ok === false ? "⚠ " : ""}{testo}</li>;
  return (
    <div style={{ marginTop: 10, background: "#161a1f", border: "1px solid #4ade8044", borderRadius: 6, padding: 12 }}>
      <div style={{ fontSize: 13, fontWeight: 700 }}>📋 Regole per questo volo</div>
      <p style={{ fontSize: 11.5, color: "#8b95a3", margin: "4px 0 0 0" }}>
        {!drone ? "Scegli il drone qui sopra per vedere le regole della sua classe."
          : info ? `${drone.nome}: classe ${chiave} (${info.peso}) → categoria Open ${info.sottocategoria}${chiave === "C2" ? " (o A3)" : ""}`
          : `${drone.nome}: classe non indicata. Se pesa meno di 250 g vale come C0 (A1); se pesa di più e non ha classe vola solo in A3 (lontano da persone e centri abitati). Aggiungi la classe in «I miei droni».`}
      </p>
      {(tipo === "agricoltura" || tipo === "pulizia") && (
        <p style={{ fontSize: 12, color: "#ffb877", background: "#241d16", border: "1px solid #4a2f16", borderRadius: 6, padding: "6px 8px", margin: "8px 0 0 0" }}>
          ⚠ {tipo === "agricoltura" ? "Trattamenti agricoli" : "Pulizia con drone"}: di solito è un'operazione in <strong>categoria Specifica</strong> (drone spesso oltre 25 kg, prodotto o getto d'acqua vicino a persone e cose). Serve un'autorizzazione ENAC o uno scenario adatto: le regole Open qui sotto da sole non bastano.
        </p>
      )}
      {tipo === "rilievo" && (
        <p style={{ fontSize: 12, color: "#c3cad4", margin: "8px 0 0 0" }}>📐 Nelle missioni automatiche il drone deve restare sempre in vista e devi poter riprendere il controllo in ogni momento.</p>
      )}
      <ul style={{ margin: "6px 0 0 0", paddingLeft: 18, fontSize: 12 }}>
        {zonaVerificata ? (
          <>
            {altezza > 0
              ? voce(null, <>Altezza massima <strong>{altezza} m dal suolo</strong>{altezzaZona != null && altezzaZona < 120 ? " (limite della zona senza autorizzazione)" : ""}</>)
              : voce(false, <>Qui <strong>senza autorizzazione non si può decollare</strong>: guarda la zona qui sopra</>)}
            {zonaApprossimata && <li style={{ marginTop: 3, color: "#f5b942" }}>⚠ Posizione approssimativa: controlla che il puntino sulla mappa sia nel posto esatto.</li>}
            {(() => {
              // permessi da chiedere per le zone in cui cade il punto
              const daChiedere = (zoneDelPunto || []).filter((z) => z.restrizione === "REQ_AUTHORISATION" || z.restrizione === "PROHIBITED");
              if (daChiedere.length === 0) return voce(true, "Permessi della zona: non serve nessuna autorizzazione per questo punto");
              return (
                <li style={{ marginTop: 4, listStyle: "none", marginLeft: -18, background: "#2a1d14", border: "1px solid #ff8c4266", borderRadius: 6, padding: "8px 10px" }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: "#ffb877" }}>🛂 Permessi da chiedere</div>
                  {daChiedere.map((z, i) => {
                    const vietata = z.restrizione === "PROHIBITED";
                    const quando = z.da > 0 ? `solo se sali oltre ${z.da} m` : "già da terra";
                    return (
                      <div key={i} style={{ fontSize: 12, color: "#e7eaee", marginTop: 4 }}>
                        • {vietata ? <>Volo <strong>vietato</strong> {quando}: si vola solo con un'esenzione</> : <><strong>Autorizzazione</strong> {quando}</>}
                        {z.ente ? <> di <strong>{z.ente}</strong></> : ""} per «{z.nome}»
                        {z.preavviso ? ` · chiedila con almeno ${durataLeggibile(z.preavviso)} di anticipo` : ""}
                        {z.email ? <> · <a href={`mailto:${z.email}`} style={{ color: "#3d8bfd" }}>{z.email}</a></> : ""}
                      </div>
                    );
                  })}
                  <div style={{ fontSize: 11.5, marginTop: 6, color: "#c3cad4" }}>Come si chiede dipende dall'ente: per le zone degli aeroporti di solito si passa dal portale D-Flight, per parchi e altri enti dal contatto indicato nella zona. Controlla la procedura nella scheda della zona su D-Flight.</div>
                  <div style={{ fontSize: 11.5, marginTop: 6, color: permessiRegistrati > 0 ? "#4ade80" : "#ffd9a0" }}>
                    {permessiRegistrati > 0 ? `✓ Hai ${permessiRegistrati === 1 ? "un permesso registrato" : `${permessiRegistrati} permessi registrati`} per questo luogo: controlla che sia valido per la data del volo.`
                      : "⚠ Non hai ancora un permesso registrato per questo luogo. Quando lo ottieni, salvalo in «Permessi» così finisce nei documenti del volo."}
                  </div>
                  <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 6 }}>
                    <button type="button" onClick={() => vaiA({ pagina: "impara", scheda: "zona-rossa", sopra: true })} style={{ background: "none", border: "1px solid #ff8c4266", color: "#ffb877", borderRadius: 5, padding: "4px 9px", fontSize: 11.5 }}>🔴 Come si chiede?</button>
                    <button type="button" onClick={() => vaiA({ pagina: "permessi" })} style={{ background: "none", border: "1px solid #333a45", color: "#c3cad4", borderRadius: 5, padding: "4px 9px", fontSize: 11.5 }}>📋 I miei permessi</button>
                  </div>
                </li>
              );
            })()}
          </>
        ) : (
          <li style={{ marginTop: 4, listStyle: "none", marginLeft: -18, background: "#3a2a12", border: "1px solid #f5b94266", borderRadius: 6, padding: "8px 10px" }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: "#ffd9a0" }}>❓ Altezza massima: zona non controllata</div>
            <div style={{ fontSize: 12, color: "#ffd9a0", marginTop: 2 }}>{MOTIVI_ZONA_NON_CONTROLLATA[motivoZona] || "controlla la zona qui sopra o su D-Flight"}.</div>
            <div style={{ fontSize: 11.5, color: "#c3cad4", marginTop: 4 }}>Il massimo di 120 m vale solo fuori dalle zone D-Flight: vicino ad aeroporti, parchi e zone protette può essere 25 m o meno, oppure serve l'autorizzazione o è vietato.</div>
            <div style={{ fontSize: 11.5, color: "#c3cad4", marginTop: 3 }}>🛂 Per lo stesso motivo non so ancora <strong>se servono permessi</strong>: lo vedi appena la zona è controllata.</div>
          </li>
        )}
        {voce(null, fpv ? "In FPV serve un osservatore accanto a te che tenga sempre il drone in vista" : "Drone sempre in vista, senza binocoli")}
        {info && info.regole.map((t, i) => <React.Fragment key={i}>{voce(null, t)}</React.Fragment>)}
        {info && info.attestato === "A2" && voce(haA2 ? true : false, haA2 ? "Attestato A2 presente tra i tuoi documenti" : "Per volare in A2 serve l'attestato A2: non lo trovo tra i tuoi attestati")}
        {info && info.attestato && voce(haA1A3 ? true : false, haA1A3 ? "Attestato A1/A3 presente tra i tuoi documenti" : "Serve l'attestato A1/A3: non lo trovo tra i tuoi attestati (o è scaduto)")}
        {voce(haAssicurazione ? true : false, haAssicurazione ? "Assicurazione RC presente e valida" : "In Italia serve l'assicurazione RC: non la trovo tra i tuoi attestati (o è scaduta)")}
        {voce(null, "Codice operatore D-Flight (QR) applicato sul drone")}
        {notte && voce(false, "Volo dopo il tramonto: accendi la luce verde lampeggiante del drone")}
      </ul>
      <p style={{ fontSize: 10.5, color: "#6b7480", margin: "8px 0 0 0" }}>Promemoria semplificato della categoria Open (Reg. UE 2019/947): controlla sempre il manuale del drone e le regole ENAC.</p>
    </div>
  );
}

// il sopralluogo si salva nel piano solo se c'è dentro qualcosa
const sopralluogoUsato = (d) => !!d && (Object.values(d.voci || {}).some(Boolean) || (d.note || "").trim() || (d.punti || []).length || (d.orari || []).length);

// --- «Manda il piano»: PDF con scene, foto, orari e sopralluogo, da mandare al cliente o a chi vola con te ----------
// immagine pronta per il PDF: piccola (lato lungo 700 px) e in JPG
async function fotoPerPdf(url, segni) {
  try {
    const href = await indirizzoVisibile(url);
    const blob = await (await fetch(href)).blob();
    const img = await new Promise((ok, no) => { const i = new Image(); i.onload = () => ok(i); i.onerror = no; i.src = URL.createObjectURL(blob); });
    const scala = Math.min(1, 700 / Math.max(img.naturalWidth, img.naturalHeight));
    const c = document.createElement("canvas");
    c.width = Math.round(img.naturalWidth * scala); c.height = Math.round(img.naturalHeight * scala);
    const ctx = c.getContext("2d");
    ctx.drawImage(img, 0, 0, c.width, c.height);
    disegnaSegni(ctx, segni, c.width, c.height);
    URL.revokeObjectURL(img.src);
    return { dati: c.toDataURL("image/jpeg", 0.8), w: c.width, h: c.height };
  } catch { return null; }
}

async function costruisciPDFPiano({ azienda, luogo, data, ora, tipo, drone, scene, sopralluogo, libreria }) {
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const grigio = [110, 120, 130];
  // i caratteri standard del PDF non hanno le frecce: le tolgo
  const pulito = (t) => String(t || "").replace(/→/g, "-").replace(/[^\x20-\x7E -ÿ–—’“”…€\n]/g, "").replace(/[ \t]{2,}/g, " ").trim();
  let y = 18;
  const spazio = (h) => { if (y + h > 282) { doc.addPage(); y = 18; } };
  const titolo = (t) => { spazio(14); y += 3; doc.setFontSize(12.5); doc.setTextColor(20, 20, 20); doc.text(pulito(t), 15, y); y += 2; doc.setDrawColor(230, 230, 230); doc.line(15, y, 195, y); y += 6; };
  const testo = (t, { x = 15, w = 180, size = 10, colore = [40, 40, 40] } = {}) => {
    doc.setFontSize(size); doc.setTextColor(...colore);
    doc.splitTextToSize(pulito(t), w).forEach((r) => { spazio(5.2); doc.text(r, x, y); y += size * 0.47; });
  };

  if (azienda?.logo) { try { doc.addImage(azienda.logo, "PNG", 15, 10, 24, 15, undefined, "FAST"); y = 32; } catch (e) { /* senza logo */ } }
  doc.setFontSize(18); doc.setTextColor(20, 20, 20); doc.text(pulito(`Piano delle riprese · ${luogo || ""}`), 15, y); y += 7;
  doc.setFontSize(10); doc.setTextColor(...grigio);
  doc.text(pulito([data ? formatData(data) : "", ora ? `ore ${ora}` : "", ETICHETTE_TIPO_PIANO[tipo] || tipo, drone ? drone.nome : "", azienda?.nome && azienda.nome !== "EyeDrones" ? azienda.nome : ""].filter(Boolean).join(" · ")), 15, y); y += 6;

  const orari = [...(sopralluogo?.orari || []).map((o) => ({ ora: o.ora, t: o.evento })), ...(scene || []).filter((x) => x.ora).map((x) => ({ ora: x.ora, t: `Scena: ${x.titolo || "senza nome"}` }))]
    .sort((a, b) => a.ora.localeCompare(b.ora));
  if (orari.length) { titolo("Orari della giornata"); orari.forEach((o) => testo(`${o.ora}   ${o.t}`)); }

  if ((scene || []).length) {
    titolo(`Scene (${scene.length})`);
    for (let i = 0; i < scene.length; i++) {
      const sc = scene[i];
      const m = (libreria || []).find((x) => x.id === sc.manovra);
      const tutteFoto = fotoDellaScena(sc);
      const foto = tutteFoto[0] ? await fotoPerPdf(tutteFoto[0].url, tutteFoto[0].segni) : null;
      const hFoto = foto ? Math.min(40, (55 * foto.h) / foto.w) : 0;
      spazio(Math.max(hFoto, 14) + 4);
      const y0 = y;
      const larg = foto ? 120 : 180;
      testo(`${i + 1}. ${sc.titolo || (m ? m.nome : "Scena")}`, { size: 11.5, colore: [20, 20, 20], w: larg });
      if (m && sc.titolo && sc.titolo !== m.nome.replace(/ \(.*\)$/, "")) testo(`Manovra: ${m.nome}`, { size: 9.5, colore: grigio, w: larg });
      const det = dettagliScena(sc, tipo).replace(/🕐 /, "ore ");
      if (det) testo(det, { size: 9.5, colore: [60, 60, 60], w: larg });
      if (sc.note) testo(sc.note, { size: 9.5, w: larg });
      if (m && m.stick) testo(`Stick: ${m.stick}`, { size: 8.5, colore: grigio, w: larg });
      if (sc.foto && sc.foto.lat != null) {
        doc.setFontSize(8.5); doc.setTextColor(40, 100, 200);
        doc.textWithLink(`Punto: ${Number(sc.foto.lat).toFixed(5)}, ${Number(sc.foto.lon).toFixed(5)} (apri la mappa)`, 15, y, { url: `https://www.google.com/maps?q=${sc.foto.lat},${sc.foto.lon}` }); y += 4.5;
      }
      if (foto) { try { doc.addImage(foto.dati, "JPEG", 140, y0 - 4, 55, hFoto, undefined, "FAST"); } catch (e) { /* foto saltata */ } y = Math.max(y, y0 - 4 + hFoto + 2); }
      // le altre foto della scena, in fila sotto
      const altre = (await Promise.all(tutteFoto.slice(1).map((f) => fotoPerPdf(f.url, f.segni)))).filter(Boolean);
      if (altre.length) {
        const hAltre = Math.max(...altre.map((f) => Math.min(40, (55 * f.h) / f.w)));
        spazio(hAltre + 2);
        altre.forEach((f, k) => { try { doc.addImage(f.dati, "JPEG", 15 + k * 60, y, 55, Math.min(40, (55 * f.h) / f.w), undefined, "FAST"); } catch (e) { /* foto saltata */ } });
        y += hAltre + 2;
      }
      y += 3;
    }
  }

  if (sopralluogo) {
    const voci = vociSopralluogo(tipo);
    const hanno = voci.some((v) => (sopralluogo.voci || {})[v.id]) || (sopralluogo.punti || []).length || (sopralluogo.note || "").trim();
    if (hanno) {
      titolo("Sopralluogo");
      voci.forEach((v) => testo(`${(sopralluogo.voci || {})[v.id] ? "[x]" : "[  ]"} ${v.testo}`, { size: 9.5, colore: (sopralluogo.voci || {})[v.id] ? [40, 40, 40] : [170, 90, 20] }));
      if ((sopralluogo.punti || []).length) {
        y += 2; testo("Punti sul posto:", { size: 10, colore: [20, 20, 20] });
        sopralluogo.punti.forEach((pt) => {
          spazio(5);
          doc.setFontSize(9.5); doc.setTextColor(40, 40, 40);
          const nome = (TIPI_PUNTO[pt.tipo] || TIPI_PUNTO.altro).nome;
          doc.textWithLink(pulito(`${nome}: ${pt.nota || "-"} (${Number(pt.lat).toFixed(5)}, ${Number(pt.lon).toFixed(5)})`), 18, y, { url: `https://www.google.com/maps?q=${pt.lat},${pt.lon}` }); y += 4.8;
        });
      }
      if ((sopralluogo.note || "").trim()) { y += 2; testo("Note:", { size: 10, colore: [20, 20, 20] }); testo(sopralluogo.note, { size: 9.5 }); }
    }
  }

  const pagine = doc.getNumberOfPages();
  for (let i = 1; i <= pagine; i++) { doc.setPage(i); doc.setFontSize(8); doc.setTextColor(...grigio); doc.text(`Preparato con EyeDrones · app.eyedrones.it · pagina ${i} di ${pagine}`, 15, 290); }
  return doc;
}

// --- Calcolatore STS-01: area di volo, contingenza e buffer per il rischio a terra -------------------------------
// Buffer: tabella STS-01 del Reg. (UE) 2019/947, Appendice 1 (drone non vincolato). Contingenza: stima con il metodo
// SORA (GPS + tempo di reazione 1 s + frenata a 45°), mai sotto i 10 m richiesti dallo scenario.
const BUFFER_STS01 = [
  { altezza: 30, leggero: 10, pesante: 20 },
  { altezza: 60, leggero: 15, pesante: 30 },
  { altezza: 90, leggero: 20, pesante: 45 },
  { altezza: 120, leggero: 25, pesante: 60 },
];

function calcolaSTS({ altezza, raggio, pesante, velocita }) {
  const H = Math.max(0, Number(altezza) || 0), R = Math.max(0, Number(raggio) || 0), V = Math.max(0, Number(velocita) || 0);
  const frenata = (V * V) / (2 * 9.81);
  const contingenza = Math.max(10, Math.ceil(3 + V * 1 + frenata));
  const altezzaContingenza = Math.ceil(H + 1 + 0.7 * V + frenata);
  const riga = BUFFER_STS01.find((x) => H <= x.altezza);
  const buffer = riga ? (pesante ? riga.pesante : riga.leggero) : null;
  return {
    altezza: H, raggio: R, velocita: V, pesante: !!pesante, contingenza, altezzaContingenza, buffer,
    raggioContingenza: R + contingenza,
    raggioTotale: buffer != null ? R + contingenza + buffer : null,
    fuoriScenario: !riga,
  };
}

// disegna le tre aree su una mappa OpenStreetMap (se le tessere non si caricano, su sfondo neutro)
async function disegnaMappaSTS({ lat, lon, sts, titolo }) {
  const L = 800, LEG = 150;
  const canvas = document.createElement("canvas");
  canvas.width = L; canvas.height = L + LEG;
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "#e9ecef"; ctx.fillRect(0, 0, L, L);
  const rMax = Math.max(sts.raggioTotale || sts.raggioContingenza || 50, 20);
  const cosLat = Math.cos((lat * Math.PI) / 180);
  const z = Math.max(3, Math.min(19, Math.floor(Math.log2((156543.03392 * cosLat * 330) / rMax))));
  const mpp = (156543.03392 * cosLat) / 2 ** z;
  const scala = 256 * 2 ** z;
  const cx = ((lon + 180) / 360) * scala;
  const latR = (lat * Math.PI) / 180;
  const cy = ((1 - Math.log(Math.tan(latR) + 1 / Math.cos(latR)) / Math.PI) / 2) * scala;
  const x0 = cx - L / 2, y0 = cy - L / 2;
  let tessere = 0;
  const carica = [];
  for (let tx = Math.floor(x0 / 256); tx <= Math.floor((x0 + L) / 256); tx++) {
    for (let ty = Math.floor(y0 / 256); ty <= Math.floor((y0 + L) / 256); ty++) {
      carica.push(new Promise((ok) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        const t = setTimeout(() => ok(), 6000);
        img.onload = () => { clearTimeout(t); ctx.drawImage(img, tx * 256 - x0, ty * 256 - y0); tessere++; ok(); };
        img.onerror = () => { clearTimeout(t); ok(); };
        img.src = `https://tile.openstreetmap.org/${z}/${((tx % 2 ** z) + 2 ** z) % 2 ** z}/${ty}.png`;
      }));
    }
  }
  await Promise.all(carica);
  const cerchio = (r, riempi, bordo) => {
    ctx.beginPath(); ctx.arc(L / 2, L / 2, r / mpp, 0, Math.PI * 2);
    ctx.fillStyle = riempi; ctx.fill(); ctx.lineWidth = 3; ctx.strokeStyle = bordo; ctx.stroke();
  };
  if (sts.raggioTotale) cerchio(sts.raggioTotale, "rgba(220,50,50,0.22)", "#d32f2f");
  cerchio(sts.raggioContingenza, "rgba(245,160,40,0.30)", "#e68a00");
  cerchio(sts.raggio, "rgba(46,160,90,0.35)", "#2e7d32");
  ctx.fillStyle = "#111"; ctx.beginPath(); ctx.arc(L / 2, L / 2, 5, 0, Math.PI * 2); ctx.fill();
  // barra della scala
  const passi = [5, 10, 20, 25, 50, 100, 200, 250, 500, 1000];
  const m = passi.find((x) => x / mpp >= 80) || 1000;
  ctx.fillStyle = "rgba(255,255,255,0.85)"; ctx.fillRect(12, L - 40, m / mpp + 24, 28);
  ctx.fillStyle = "#111"; ctx.fillRect(24, L - 22, m / mpp, 4);
  ctx.font = "bold 13px sans-serif"; ctx.fillText(`${m} m`, 24, L - 26);
  ctx.font = "11px sans-serif"; ctx.fillStyle = "rgba(255,255,255,0.85)"; ctx.fillRect(L - 190, L - 18, 190, 18);
  ctx.fillStyle = "#333"; ctx.fillText("© OpenStreetMap contributors", L - 182, L - 5);
  // legenda
  ctx.fillStyle = "#ffffff"; ctx.fillRect(0, L, L, LEG);
  ctx.fillStyle = "#111"; ctx.font = "bold 18px sans-serif"; ctx.fillText(titolo || "STS-01 · volume operativo", 16, L + 28);
  const voce = (y, colore, testo) => { ctx.fillStyle = colore; ctx.fillRect(16, y - 12, 16, 16); ctx.fillStyle = "#222"; ctx.font = "15px sans-serif"; ctx.fillText(testo, 40, y + 1); };
  voce(L + 56, "#2e7d32", `Area di volo: raggio ${sts.raggio} m · altezza max ${sts.altezza} m`);
  voce(L + 82, "#e68a00", `Contingenza: +${sts.contingenza} m (raggio ${sts.raggioContingenza} m) · altezza ${sts.altezzaContingenza} m`);
  if (sts.raggioTotale) voce(L + 108, "#d32f2f", `Buffer rischio a terra: +${sts.buffer} m (area controllata a terra: raggio ${sts.raggioTotale} m)`);
  ctx.fillStyle = "#666"; ctx.font = "12px sans-serif";
  ctx.fillText(`Centro ${lat.toFixed(5)}, ${lon.toFixed(5)}${tessere === 0 ? " · mappa non disponibile, solo le aree" : ""}`, 16, L + 136);
  const dataUrl = canvas.toDataURL("image/png");
  const blob = await new Promise((ok) => canvas.toBlob(ok, "image/png"));
  return { dataUrl, blob, conMappa: tessere > 0 };
}

function CalcolatoreSTS({ punto, valore, onCambia, nomeLuogo, chiave }) {
  const [aperto, setAperto] = useState(!!valore);
  const [campi, setCampi] = useState(() => ({ altezza: String(valore?.altezza ?? 60), raggio: String(valore?.raggio ?? 50), velocita: String(valore?.velocita ?? 5), pesante: !!valore?.pesante }));
  const [immagine, setImmagine] = useState(null); // { dataUrl, blob } appena disegnata
  const [disegnando, setDisegnando] = useState(false);
  // cambia piano (aperto, nuovo o annullato): riparto dai valori salvati in quel piano
  useEffect(() => {
    setAperto(!!valore);
    if (valore) setCampi({ altezza: String(valore.altezza ?? 60), raggio: String(valore.raggio ?? 50), velocita: String(valore.velocita ?? 5), pesante: !!valore.pesante });
    setImmagine(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [chiave]);
  const r = calcolaSTS(campi);
  const aggiorna = (k, v) => {
    const nuovi = { ...campi, [k]: v };
    setCampi(nuovi);
    setImmagine(null);
    onCambia({ ...calcolaSTS(nuovi), scenario: "STS-01", immagine_url: null });
  };
  const disegna = async () => {
    if (!punto) return;
    setDisegnando(true);
    try {
      const img = await disegnaMappaSTS({ lat: punto.lat, lon: punto.lon, sts: r, titolo: `STS-01 · ${nomeLuogo || "volume operativo"}` });
      setImmagine(img);
      onCambia({ ...r, scenario: "STS-01", immagine_url: null, immagineNuova: img });
    } catch (e) {
      alert("Non sono riuscito a disegnare la mappa: " + (e?.message || e));
    }
    setDisegnando(false);
  };
  const campo = (k, etichetta, unita) => (
    <label style={{ fontSize: 11, color: "#6b7480", display: "flex", flexDirection: "column", gap: 3, flex: "1 1 120px" }}>
      {etichetta}
      <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
        <input type="number" inputMode="decimal" value={campi[k]} onChange={(e) => aggiorna(k, e.target.value)} style={{ ...inputStyle, padding: "6px 8px" }} />
        <span style={{ fontSize: 11, color: "#8b95a3" }}>{unita}</span>
      </div>
    </label>
  );
  if (!aperto) {
    return (
      <button type="button" onClick={() => { setAperto(true); onCambia({ ...r, scenario: "STS-01", immagine_url: null }); }} style={{ marginTop: 10, background: "#161a1f", border: "1px dashed #a78bfa88", color: "#c4b5fd", borderRadius: 6, padding: "10px 12px", fontSize: 12.5, fontWeight: 600, textAlign: "left", width: "100%" }}>
        📐 Voli in STS-01? Calcola contingenza e buffer e disegnali sulla mappa
      </button>
    );
  }
  const riga = (colore, nome, testo) => (
    <div style={{ display: "flex", gap: 8, alignItems: "baseline", fontSize: 12.5, marginTop: 4 }}>
      <span style={{ width: 10, height: 10, borderRadius: 2, background: colore, flexShrink: 0, display: "inline-block" }} />
      <span style={{ color: "#8b95a3", minWidth: 130 }}>{nome}</span><span style={{ color: "#e7eaee" }}>{testo}</span>
    </div>
  );
  return (
    <div style={{ marginTop: 10, background: "#161a1f", border: "1px solid #a78bfa55", borderRadius: 6, padding: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 13, fontWeight: 700 }}>📐 Volumi STS-01<EtichettaPro /></span>
        <button type="button" onClick={() => { setAperto(false); setImmagine(null); onCambia(null); }} style={{ background: "none", border: "none", color: "#8b95a3", fontSize: 12 }}>Togli</button>
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 8 }}>
        {campo("altezza", "Altezza massima di volo", "m")}
        {campo("raggio", "Raggio dell'area di volo", "m")}
        {campo("velocita", "Velocità massima", "m/s")}
      </div>
      <div style={{ display: "flex", gap: 6, marginTop: 8, flexWrap: "wrap" }}>
        {[[false, "Fino a 10 kg"], [true, "Oltre 10 kg"]].map(([v, t]) => (
          <button key={t} type="button" onClick={() => aggiorna("pesante", v)} style={{ background: campi.pesante === v ? "#a78bfa22" : "#262b33", border: `1px solid ${campi.pesante === v ? "#a78bfa" : "#333a45"}`, color: campi.pesante === v ? "#c4b5fd" : "#c3cad4", borderRadius: 6, padding: "6px 10px", fontSize: 12 }}>{t} al decollo</button>
        ))}
      </div>
      <div style={{ marginTop: 10, paddingTop: 8, borderTop: "1px solid #262b33" }}>
        {riga("#2e7d32", "Area di volo", `raggio ${r.raggio} m · fino a ${r.altezza} m`)}
        {riga("#e68a00", "Contingenza", `+${r.contingenza} m (raggio ${r.raggioContingenza} m) · fino a ${r.altezzaContingenza} m`)}
        {r.fuoriScenario
          ? <p style={{ fontSize: 12, color: "#ff9c9c", margin: "6px 0 0 0" }}>Oltre 120 m di altezza si esce dallo scenario STS-01.</p>
          : riga("#d32f2f", "Buffer rischio a terra", `+${r.buffer} m → area controllata a terra: raggio ${r.raggioTotale} m`)}
        <p style={{ fontSize: 10.5, color: "#6b7480", margin: "6px 0 0 0" }}>Buffer dalla tabella STS-01 (Reg. UE 2019/947, Appendice 1). Contingenza stimata con GPS 3 m + reazione 1 s + frenata, minimo 10 m: usa sempre i valori del tuo manuale operativo STS.</p>
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 10, alignItems: "center" }}>
        <button type="button" onClick={disegna} disabled={!punto || disegnando || r.fuoriScenario} style={{ background: punto ? "#a78bfa" : "#333a45", color: punto ? "#161a1f" : "#6b7480", border: "none", borderRadius: 6, padding: "7px 12px", fontSize: 12.5, fontWeight: 700 }}>
          {disegnando ? "Disegno…" : "🗺️ Disegna sulla mappa"}
        </button>
        {!punto && <span style={{ fontSize: 11.5, color: "#f5b942" }}>Serve il punto: coordinate, indirizzo trovato o «Controlla meteo».</span>}
        {immagine && <a href={immagine.dataUrl} download={`sts01-${(nomeLuogo || "volo").replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.png`} style={{ color: "#c4b5fd", fontSize: 12.5 }}>⬇️ Scarica immagine</a>}
      </div>
      {immagine ? (
        <>
          <img src={immagine.dataUrl} alt="Aree STS-01" style={{ width: "100%", maxWidth: 420, borderRadius: 6, marginTop: 8, display: "block" }} />
          <p style={{ fontSize: 11, color: "#8b95a3", margin: "4px 0 0 0" }}>{immagine.conMappa ? "" : "Mappa non raggiungibile ora: disegnate solo le aree. "}L'immagine si salva con il piano («Salva piano») e va nel fascicolo del volo.</p>
        </>
      ) : valore?.immagine_url ? (
        <ImmagineFile src={valore.immagine_url} alt="Aree STS-01" style={{ width: "100%", maxWidth: 420, borderRadius: 6, marginTop: 8, display: "block" }} />
      ) : null}
    </div>
  );
}

// --- Strumenti per i lavori speciali: rilievo/fotogrammetria, agricoltura, pulizia -----------------------------------

// fotocamere: larghezza sensore (mm), focale reale (mm), larghezza immagine (px). Valori indicativi dalle schede tecniche.
const FOTOCAMERE_RILIEVO = [
  { key: "p4rtk", nome: "DJI Phantom 4 RTK", sensore: 13.2, focale: 8.8, px: 5472 },
  { key: "m3e", nome: "DJI Mavic 3 Enterprise / Matrice 4E (grandangolo)", sensore: 17.3, focale: 12.29, px: 5280 },
  { key: "mini", nome: "DJI Mini 3/4 Pro, Air 3 (12 MP)", sensore: 9.6, focale: 6.72, px: 4032 },
  { key: "manuale", nome: "Altra fotocamera (inserisco i dati)", sensore: 13.2, focale: 8.8, px: 5472 },
];

// GSD in cm/pixel ↔ altezza in metri: GSD = sensore × H / (focale × px)
const gsdDaAltezza = (c, h) => (c.sensore * h * 100) / (c.focale * c.px);
const altezzaDaGsd = (c, g) => (g * c.focale * c.px) / (c.sensore * 100);

function calcolaMissioneRilievo({ cam, modo, valore, frontale, laterale, ettari, velocita, autonomia }) {
  const H = modo === "altezza" ? Number(valore) || 0 : altezzaDaGsd(cam, Number(valore) || 0);
  const gsd = modo === "gsd" ? Number(valore) || 0 : gsdDaAltezza(cam, H);
  const larg = (gsd * cam.px) / 100; // impronta a terra, lato lungo dell'immagine (m)
  const alt = larg * 0.75; // lato corto (immagini 4:3)
  const traStrisciate = larg * (1 - (Number(laterale) || 0) / 100);
  const traScatti = alt * (1 - (Number(frontale) || 0) / 100);
  const lato = Math.sqrt(Math.max(0, Number(ettari) || 0) * 10000); // area pensata come un quadrato
  const strisciate = traStrisciate > 0 ? Math.ceil(lato / traStrisciate) + 1 : 0;
  const fotoPerStrisciata = traScatti > 0 ? Math.ceil(lato / traScatti) + 1 : 0;
  const v = Math.max(0.5, Number(velocita) || 0);
  const percorso = strisciate * lato + Math.max(0, strisciate - 1) * traStrisciate;
  const minuti = percorso / v / 60;
  const utile = Math.max(1, (Number(autonomia) || 0) * 0.75); // tengo il 25% di riserva
  return {
    H, gsd, larg, alt, traStrisciate, traScatti, foto: strisciate * fotoPerStrisciata, strisciate,
    minuti, batterie: Math.max(1, Math.ceil(minuti / utile)), intervallo: traScatti / v,
  };
}

function CalcolatoreRilievo() {
  const [camKey, setCamKey] = useState("p4rtk");
  const [manuale, setManuale] = useState({ sensore: "13.2", focale: "8.8", px: "5472" });
  const [modo, setModo] = useState("altezza");
  const [c, setC] = useState({ valore: "80", frontale: "80", laterale: "70", ettari: "5", velocita: "8", autonomia: "25" });
  const base = FOTOCAMERE_RILIEVO.find((x) => x.key === camKey);
  const cam = camKey === "manuale" ? { ...base, sensore: Number(manuale.sensore) || 1, focale: Number(manuale.focale) || 1, px: Number(manuale.px) || 1 } : base;
  const r = calcolaMissioneRilievo({ cam, modo, ...c });
  const f1 = (n) => n.toLocaleString("it-IT", { maximumFractionDigits: 1 });
  const campo = (k, etichetta, unita, oggetto = c, set = setC) => (
    <label style={{ fontSize: 11, color: "#6b7480", display: "flex", flexDirection: "column", gap: 3, flex: "1 1 110px" }}>
      {etichetta}
      <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
        <input type="number" inputMode="decimal" value={oggetto[k]} onChange={(e) => set({ ...oggetto, [k]: e.target.value })} style={{ ...inputStyle, padding: "6px 8px" }} />
        <span style={{ fontSize: 11, color: "#8b95a3" }}>{unita}</span>
      </span>
    </label>
  );
  const risultato = (t, v, avviso) => (
    <div style={{ background: "#1b2028", border: `1px solid ${avviso ? "#f5b94266" : "#262b33"}`, borderRadius: 6, padding: "8px 10px", minWidth: 0 }}>
      <div style={{ fontSize: 10.5, color: "#8b95a3" }}>{t}</div>
      <div className="mono" style={{ fontSize: 15, fontWeight: 600, color: avviso ? "#f5b942" : "#e7eaee" }}>{v}</div>
    </div>
  );
  return (
    <div>
      <select value={camKey} onChange={(e) => setCamKey(e.target.value)} style={{ ...inputStyle, fontSize: 12.5 }}>
        {FOTOCAMERE_RILIEVO.map((x) => <option key={x.key} value={x.key}>{x.nome}</option>)}
      </select>
      {camKey === "manuale" && (
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 8 }}>
          {campo("sensore", "Larghezza sensore", "mm", manuale, setManuale)}
          {campo("focale", "Focale reale", "mm", manuale, setManuale)}
          {campo("px", "Larghezza foto", "px", manuale, setManuale)}
        </div>
      )}
      <div style={{ display: "flex", gap: 6, marginTop: 8 }}>
        {[["altezza", "Parto dall'altezza"], ["gsd", "Parto dal dettaglio (GSD)"]].map(([k, t]) => (
          <button key={k} type="button" onClick={() => { setModo(k); setC({ ...c, valore: k === "altezza" ? String(Math.round(r.H)) : f1(r.gsd).replace(",", ".") }); }} style={{ background: modo === k ? "#22d3ee22" : "#262b33", border: `1px solid ${modo === k ? "#22d3ee" : "#333a45"}`, color: modo === k ? "#67e8f9" : "#c3cad4", borderRadius: 6, padding: "6px 10px", fontSize: 12 }}>{t}</button>
        ))}
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 8 }}>
        {campo("valore", modo === "altezza" ? "Altezza di volo" : "Dettaglio voluto (GSD)", modo === "altezza" ? "m" : "cm/px")}
        {campo("frontale", "Sovrapposizione frontale", "%")}
        {campo("laterale", "Sovrapposizione laterale", "%")}
        {campo("ettari", "Area da rilevare", "ha")}
        {campo("velocita", "Velocità", "m/s")}
        {campo("autonomia", "Autonomia batteria", "min")}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(130px, 1fr))", gap: 6, marginTop: 10 }}>
        {risultato("Dettaglio (GSD)", `${f1(r.gsd)} cm/px`)}
        {risultato("Altezza di volo", `${Math.round(r.H)} m`, r.H > 120)}
        {risultato("Impronta di una foto", `${Math.round(r.larg)} × ${Math.round(r.alt)} m`)}
        {risultato("Distanza tra strisciate", `${f1(r.traStrisciate)} m`)}
        {risultato("Distanza tra scatti", `${f1(r.traScatti)} m`)}
        {risultato("Uno scatto ogni", `${f1(r.intervallo)} s`, r.intervallo < 2)}
        {risultato("Foto stimate", `${r.foto.toLocaleString("it-IT")}`)}
        {risultato("Tempo di volo", `${Math.round(r.minuti)} min`)}
        {risultato("Batterie", `${r.batterie}`)}
      </div>
      {r.H > 120 && <p style={{ fontSize: 11.5, color: "#f5b942", margin: "6px 0 0 0" }}>Oltre 120 m non si vola in categoria Open: abbassa la quota o aumenta il GSD.</p>}
      {r.intervallo < 2 && <p style={{ fontSize: 11.5, color: "#f5b942", margin: "6px 0 0 0" }}>Uno scatto ogni meno di 2 secondi: molte fotocamere non ce la fanno. Rallenta o vola più in alto.</p>}
      <p style={{ fontSize: 10.5, color: "#6b7480", margin: "8px 0 0 0" }}>Stima per un'area quadrata pianeggiante, con il 25% di batteria di riserva. Dati delle fotocamere indicativi: controlla la scheda tecnica della tua. Per rilievi di qualche ettaro di solito bastano 6–8 punti di controllo a terra ben distribuiti, più 2–3 punti di verifica.</p>
    </div>
  );
}

function CalcolatoreTrattamento() {
  const [c, setC] = useState({ ettari: "3", dose: "15", serbatoio: "40", ettariOra: "6" });
  const n = (k) => Number(String(c[k]).replace(",", ".")) || 0;
  const litri = n("ettari") * n("dose");
  const pieni = n("serbatoio") > 0 ? Math.ceil(litri / n("serbatoio")) : 0;
  const ore = n("ettariOra") > 0 ? n("ettari") / n("ettariOra") : 0;
  const campo = (k, etichetta, unita) => (
    <label style={{ fontSize: 11, color: "#6b7480", display: "flex", flexDirection: "column", gap: 3, flex: "1 1 110px" }}>
      {etichetta}
      <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
        <input type="number" inputMode="decimal" value={c[k]} onChange={(e) => setC({ ...c, [k]: e.target.value })} style={{ ...inputStyle, padding: "6px 8px" }} />
        <span style={{ fontSize: 11, color: "#8b95a3" }}>{unita}</span>
      </span>
    </label>
  );
  return (
    <div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {campo("ettari", "Superficie", "ha")}
        {campo("dose", "Volume per ettaro", "l/ha")}
        {campo("serbatoio", "Serbatoio del drone", "l")}
        {campo("ettariOra", "Resa del drone", "ha/ora")}
      </div>
      <div className="mono" style={{ display: "flex", gap: "6px 18px", flexWrap: "wrap", fontSize: 13.5, marginTop: 10 }}>
        <span>💧 {litri.toLocaleString("it-IT", { maximumFractionDigits: 1 })} l di miscela</span>
        <span>🛢️ {pieni} {pieni === 1 ? "pieno" : "pieni"} del serbatoio</span>
        <span>⏱️ circa {ore.toLocaleString("it-IT", { maximumFractionDigits: 1 })} ore</span>
      </div>
      <p style={{ fontSize: 11, color: "#ffb877", margin: "8px 0 0 0", lineHeight: 1.5 }}>Trattamenti con prodotti fitosanitari: la Legge 182/2025 ha aperto una sperimentazione fino al 2028, ma servono il decreto attuativo, un prodotto la cui etichetta preveda l'uso aereo e le abilitazioni del pilota (es. PDRA-S01). Prima di ogni lavoro verifica che cosa è consentito oggi. La mappatura multispettrale (NDVI) segue invece le regole normali di volo.</p>
    </div>
  );
}

function CalcolatorePulizia() {
  const [c, setC] = useState({ altezza: "15", larghezza: "20", resa: "100" });
  const n = (k) => Number(String(c[k]).replace(",", ".")) || 0;
  const superficie = n("altezza") * n("larghezza");
  const ore = n("resa") > 0 ? superficie / n("resa") : 0;
  const campo = (k, etichetta, unita) => (
    <label style={{ fontSize: 11, color: "#6b7480", display: "flex", flexDirection: "column", gap: 3, flex: "1 1 110px" }}>
      {etichetta}
      <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
        <input type="number" inputMode="decimal" value={c[k]} onChange={(e) => setC({ ...c, [k]: e.target.value })} style={{ ...inputStyle, padding: "6px 8px" }} />
        <span style={{ fontSize: 11, color: "#8b95a3" }}>{unita}</span>
      </span>
    </label>
  );
  return (
    <div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {campo("altezza", "Altezza della superficie", "m")}
        {campo("larghezza", "Larghezza", "m")}
        {campo("resa", "La tua resa", "m²/ora")}
      </div>
      <div className="mono" style={{ display: "flex", gap: "6px 18px", flexWrap: "wrap", fontSize: 13.5, marginTop: 10 }}>
        <span>▦ {superficie.toLocaleString("it-IT", { maximumFractionDigits: 0 })} m² da pulire</span>
        <span>⏱️ circa {ore.toLocaleString("it-IT", { maximumFractionDigits: 1 })} ore di lavoro</span>
        <span>🚧 area a terra da delimitare: almeno {Math.ceil(n("altezza"))} m dalla superficie</span>
      </div>
      <p style={{ fontSize: 10.5, color: "#6b7480", margin: "8px 0 0 0", lineHeight: 1.5 }}>L'area di sicurezza segue la regola «1:1» (distanza a terra almeno pari all'altezza di lavoro), usata come riferimento nelle valutazioni del rischio: quella da rispettare è scritta nella tua autorizzazione ENAC. La pulizia con drone è quasi sempre in categoria Specifica.</p>
    </div>
  );
}

